league_hidden_state.script:
const R = ["League Copper Standing", "League Bronze Standing", "League Silver Standing", "League Gold Standing", "League Platinum Standing", "League Champion"]
const C = [["Copper deeds: 0/2 toward Bronze", "Copper deeds: 1/2 toward Bronze", "Copper deeds: 2/2 toward Bronze"], ["Bronze deeds: 0/3 toward Silver", "Bronze deeds: 1/3 toward Silver", "Bronze deeds: 2/3 toward Silver", "Bronze deeds: 3/3 toward Silver"], ["Silver deeds: 0/4 toward Gold", "Silver deeds: 1/4 toward Gold", "Silver deeds: 2/4 toward Gold", "Silver deeds: 3/4 toward Gold", "Silver deeds: 4/4 toward Gold"], ["Gold deeds: 0/5 toward Platinum", "Gold deeds: 1/5 toward Platinum", "Gold deeds: 2/5 toward Platinum", "Gold deeds: 3/5 toward Platinum", "Gold deeds: 4/5 toward Platinum", "Gold deeds: 5/5 toward Platinum"]]
const Q = [2, 3, 4, 5]
const T = check({type:'player-traits'}) || {}
const book = (storage.rankLedger = storage.rankLedger || {}).league = {}
const lines = []
let member = false
for (const [name, list] of Object.entries(T)) {
  let r = R.length - 1
  while (r >= 0 && !list.includes(R[r])) r--
  if (r < 0) continue
  member = true
  if (r < 4) {
    let c = 0
    for (let i = 0; i < C[r].length; i++) if (list.includes(C[r][i])) c = i
    book[name] = {r, c}
    lines.push(name + ': ' + R[r] + '; BEFORE this scene: ' + c + '/' + Q[r] + ' already recorded toward ' + R[r+1] + (c < Q[r] ? '; if ONE new deed is accepted NOW, announce ' + (c+1) + '/' + Q[r] + ' afterward' : '') + (c === Q[r] ? '; eligible for formal promotion' : c === Q[r]-1 ? '; ONE further accepted deed permits promotion in this scene' : '; NOT eligible for promotion this scene; at most one deed may be credited'))
  } else lines.push(name + ': ' + R[r] + (r === 4 ? '; requires a specifically accepted exceptional commission, completed afterward, then personal Council investiture' : '; permanent Champion'))
}
storage.leagueMember = member
storage.leagueIndividualRecognitionVersion = 3
if (lines.length) effects.push({type:'story',instruction:('League record: ' + lines.join('. ') + '. These starting totals override any mistaken total in earlier dialogue. Add this scene’s accepted deed to the starting total; do not recount only the deeds mentioned in recent conversation. These counts govern eligibility. A premature announcement does not change standing; correct it in the next scene and invite missing deeds individually.').slice(0,1000)})

