league_crew_finding_guidance.script:
if (storage.inLeagueCrewSpace !== true) { skip = true }

if (!skip) {
  effects.push({ type: 'story', instruction: 'IF the party is looking for a crew, companion, partner, backup, hireling, guide, specialist, introduction, or pin-call in this League space, first consider competent authored NPCs already established in the area or settlement whose goals and abilities genuinely fit the request. For a specific role or class request, use the League pin-call to bring exactly one suitable available candidate into the Hall in this same response; do not make the party wait for a later turn. For a broad request to build a party, present only 2-3 distinct candidates, using varied roles and considering a front-liner, caster, healer, or utility character where useful. Favor non-human options. Give each candidate a name, species, role, demonstrated competence, present disposition, and one clear reason they may fit or clash with the party. Show their arrival and immediate presence rather than giving each one a speech about similar work. The local guildmaster, chaptermaster, or authored veteran may introduce possibilities, never assign them. Do not make every candidate immediately devoted, agreeable, or available for any purpose. Let the player choose, refuse, negotiate, test, or ignore them; a candidate does not join the party without explicit agreement.' })
}

tower_shadow_rite_ceremony.script:
const CONTEXT=["Inquisition Credit Standing: 1", "Inquisition Credit Standing: 2", "Inquisition Credit Standing: 3", "Inquisition Credit Standing: 4"];
const R = ["Shadow Initiate", "Shadow Inquisitor", "Inquisition Adept", "Master Inquisitor"]
const Q = [1, 3, 4]
const T = check({ type: 'player-traits' }) || {}
const B = (storage.rankLedger && storage.rankLedger["inquisition"]) || {}
const rk = (n) => { const l = T[n] || []; for (let i = R.length - 1; i >= 0; i--) if (l.includes(R[i])) return i; return -1 }
const COUNTS = [["Inquisition record (Shadow Initiate): 0/1", "Inquisition record (Shadow Initiate): 1/1"], ["Inquisition record (Shadow Inquisitor): 0/3", "Inquisition record (Shadow Inquisitor): 1/3", "Inquisition record (Shadow Inquisitor): 2/3", "Inquisition record (Shadow Inquisitor): 3/3"], ["Inquisition record (Inquisition Adept): 0/4", "Inquisition record (Inquisition Adept): 1/4", "Inquisition record (Inquisition Adept): 2/4", "Inquisition record (Inquisition Adept): 3/4", "Inquisition record (Inquisition Adept): 4/4"], []]
const PENDING=["Inquisition Credit Pending", "Inquisition Credit Pending", "Inquisition Credit Pending", ""];
const cr = (n) => {const r=rk(n);return Math.min(Q[r]||0,Math.max(0,(COUNTS[r]||[]).findIndex(x=>(T[n]||[]).includes(x)))+(((T[n]||[]).includes(PENDING[r])&&(T[n]||[]).includes(CONTEXT[r]))?1:0))}
const N = Object.keys(T)
const at = (i) => N.filter((n) => rk(n) === i)
const ready = (i) => at(i).filter((n) => Q[i] && cr(n) >= Q[i])
const both = (l) => l.length > 1 ? l.slice(0, -1).join(', ') + ' and ' + l[l.length - 1] : (l[0] || '')
const due = ready(0).filter((n) => !(B[n] && B[n].told === 0))
if (!due.length) { skip = true } else {
  for (const n of due) storage.rankLedger["inquisition"][n].told = 0
  effects.push({ type: 'story', instruction: 'For ' + both(due) + ': ' + "Create a significant, interactive Rite of Bonding at the Pit of Shadow for the qualified Initiate. The order has authorized the rite because of the completed field case. Bring Jett, the character’s mentor, Iliora, or another proper authority into the scene as witnesses and guides. Establish the choice and cost of the bond before resolving it; do not decide the character’s consent, words, offering, or reaction. If the character accepts, the Pit answers and a Shade emerges: an uncanny figure almost human, its details wrong like a reflection in dark water. The Shade may communicate through gesture, sensation, images, or silence according to the emerging story; do not contradict established characterization or force it to speak. Make clear that the bond is permanent, grants Shade-Sight and a supernatural partner in the work, and marks the character’s rise from Initiate to full Inquisitor. Keep the rite solemn, strange, and earned rather than treating it as a casual ability pickup." })
}

