tower_dead_hunt_named_guidance.script:
const campaign = storage.towerDeadHunt
if (!campaign || campaign.active !== true) { skip = true }

if (!skip) {
  const defeated = Array.isArray(campaign.defeatedNamedDead) ? campaign.defeatedNamedDead : []
  const allDead = ['Vortigar the Unburied', 'Sethelle of the Nine Sorrows', 'Karneth Draghmar', 'The Lady Mavrocine', 'Ossarine the Pale Crown', 'Belugar Thoth-Amon', 'Druathyr the Thrice-Drowned']
  const remaining = allDead.filter(name => !defeated.includes(name))
  effects.push({ type: 'story', instruction: '# Named Dead Hunt Guidance\n\nThe player is now an Inquisitor and may pursue the Seven Named Dead. Remaining targets: ' + (remaining.length ? remaining.join(', ') : 'none') + '. Surface leads through Inquisition case files, Jett, Tarain Rethford, Iliora, Shade-Sight, victims, grave signs, cursed relics, Shadelands dreams, or dreamed worlds. Do not force a fixed order, though Vortigar the Unburied is the clearest first case if the player asks where to begin. Each named dead may be resolved by the appropriate means: destroyed, laid to rest, exorcised, bound, redeemed, exposed, buried, unmade, or otherwise ended so they can no longer threaten the living.' })
}

