const col = (n) => (T[n] || []).find((x) => COL.includes(x)) || ''
const chose = (n) => { const i = CHOSE.findIndex((c) => has(n, c)); return i < 0 ? '' : COL[i] }
const both = (l) => l.length > 1 ? l.slice(0, -1).join(', ') + ' and ' + l[l.length - 1] : (l[0] || '')
