templars_adamant_board_of_works.script:
const CONTEXT=["Templars Credit Standing: 1", "Templars Credit Standing: 2", "Templars Credit Standing: 3", "Templars Credit Standing: 4"];
const R = ["Templar Initiate", "Templar Adamant", "Templar Captain", "Templar Champion"]
const Q = [1, 3, 4]
const T = check({ type: 'player-traits' }) || {}
