const ready = (i) => at(i).filter((n) => Q[i] && cr(n) >= Q[i])
const both = (l) => l.length > 1 ? l.slice(0, -1).join(', ') + ' and ' + l[l.length - 1] : (l[0] || '')
const G = ["Offer exactly three contained first shield-works suitable for a Templar Initiate: one protecting warders while they seal a small breach, one defending people or sacred ground from a specific undead threat, and one recovering a blessed relic or destroying a single undead anchor. Name the place, affected people, known danger, decisive success, and a supervising Templar who advises without leading or solving it.", "Offer independent shield-work with a named place, people at risk, clear supernatural pressure, decisive objective, and useful reward: seal a breach, defend a rite, purge an undead-held site, recover a pursued relic, escort a priest or warder, or destroy what anchors a haunting. Treat the character as the Templar expected to solve it.", "Offer a great shield-work requiring field command: several warders or Templars, a major stronghold or breach, linked threatened sites, a large defensive withdrawal, or a difficult purge whose rites and battle must be coordinated. Keep the character the protagonist and decision-maker.", "Offer an order-defining operation worthy of a Templar Champion: a major Shadelands breach, vampire-era power, regional undead offensive, or a strategic step toward sealing the Pit of Shadow. Treat the character as a senior champion directing the response, not as hired muscle or automatic temple ruler."]
