const R = ["Templar Initiate", "Templar Adamant", "Templar Captain", "Templar Champion"]
const Q = [1, 3, 4]
const T = check({ type: 'player-traits' }) || {}
const B = (storage.rankLedger && storage.rankLedger["templars"]) || {}
const rk = (n) => { const l = T[n] || []; for (let i = R.length - 1; i >= 0; i--) if (l.includes(R[i])) return i; return -1 }
const COUNTS = [["Templars record (Templar Initiate): 0/1", "Templars record (Templar Initiate): 1/1"], ["Templars record (Templar Adamant): 0/3", "Templars record (Templar Adamant): 1/3", "Templars record (Templar Adamant): 2/3", "Templars record (Templar Adamant): 3/3"], ["Templars record (Templar Captain): 0/4", "Templars record (Templar Captain): 1/4", "Templars record (Templar Captain): 2/4", "Templars record (Templar Captain): 3/4", "Templars record (Templar Captain): 4/4"], []]
const PENDING=["Templars Credit Pending", "Templars Credit Pending", "Templars Credit Pending", ""];
const cr = (n) => {const r=rk(n);return Math.min(Q[r]||0,Math.max(0,(COUNTS[r]||[]).findIndex(x=>(T[n]||[]).includes(x)))+(((T[n]||[]).includes(PENDING[r])&&(T[n]||[]).includes(CONTEXT[r]))?1:0))}
const N = Object.keys(T)
const at = (i) => N.filter((n) => rk(n) === i)
const ready = (i) => at(i).filter((n) => Q[i] && cr(n) >= Q[i])
const both = (l) => l.length > 1 ? l.slice(0, -1).join(', ') + ' and ' + l[l.length - 1] : (l[0] || '')
const due = ready(1).filter((n) => !(B[n] && B[n].told === 1))
if (!due.length) { skip = true } else {
  for (const n of due) storage.rankLedger["templars"][n].told = 1
  effects.push({ type: 'story', instruction: 'For ' + both(due) + ': ' + "Create an earned, interactive promotion from Templar Adamant to Templar Captain in the Hall of Shields. Use the three recognized works and the people, warders, restored places, or destroyed anchors involved to establish readiness for command. If accepted, grant authority to direct field wards, sealing rites, and willing Templars. Award a specifically named Superior captain’s item suited to the character’s build—a weapon, focus, shield, armor piece, ward-standard, or field implement—with exact form, materials, magical aspect, and useful protective or radiant property. Do not assign followers automatically or dictate how the character leads." })
}

