knights_vigilant_hidden_state.script:
const CONTEXT=["Vigilant Credit Standing: 1", "Vigilant Credit Standing: 2", "Vigilant Credit Standing: 3", "Vigilant Credit Standing: 4"];
const R = ["New-Sworn", "Moor-Knight", "Banner-Knight", "Champion Vigilant"]
