const PENDING=["Vigilant Credit Pending", "Vigilant Credit Pending", "Vigilant Credit Pending", ""];
const cr = (n) => {const r=rk(n);return Math.min(Q[r]||0,Math.max(0,(COUNTS[r]||[]).findIndex(x=>(T[n]||[]).includes(x)))+(((T[n]||[]).includes(PENDING[r])&&(T[n]||[]).includes(CONTEXT[r]))?1:0))}
const N = Object.keys(T)
const at = (i) => N.filter((n) => rk(n) === i)
const ready = (i) => at(i).filter((n) => Q[i] && cr(n) >= Q[i])
const both = (l) => l.length > 1 ? l.slice(0, -1).join(', ') + ' and ' + l[l.length - 1] : (l[0] || '')
const M = storage.rankLedgerMigrated = storage.rankLedgerMigrated || {}
if (!M["knights"]) {
  M["knights"] = true
  const oldRank = ["new_sworn", "moor_knight", "banner_knight", "champion"].indexOf((storage.guilds && storage.guilds.knightsVigilant || {}).rank)
  if (oldRank >= 0) {
    const led = storage.rankLedger = storage.rankLedger || {}
    const book = led["knights"] = led["knights"] || {}
    const holders = N.filter((n) => rk(n) >= 0)
    if (!holders.length) effects.push({ type: 'player-traits', operator: 'add', value: R[oldRank] })
    const oldCredits = Number(storage.guilds.knightsVigilant.rideCredits) || 0
    for (const n of (holders.length ? holders : N)) {
      const r = holders.length ? rk(n) : oldRank
      if (r === oldRank && Q[r]) book[n] = { r, c: Math.min(Q[r], oldCredits), t: -1, told: -1 }
    }
  }
}
const lines = N.map((n) => { const i = rk(n); if (i < 0) return n + ': not a member'; return n + ': ' + R[i] + (Q[i] ? ', ' + cr(n) + ' of ' + Q[i] + ' recognized rides toward ' + R[i + 1] : '') })
const MEAN = ["A newly oathbound knight expected to complete one first ride under a veteran’s eye.", "A proven knight trusted to answer undead hunts independently.", "A recognized leader who bears a personal banner and leads larger rides.", "A celebrated Champion Vigilant who commands great rides, judges deeds, and rallies settlements against the dead."]
const seen = [...new Set(N.map(rk).filter((i) => i >= 0))].map((i) => MEAN[i]).filter(Boolean)
effects.push({ type: 'story', instruction: "Hidden Knights Vigilant standing, by character: " + lines.join('; ') + '. ' + seen.join(' ') + " Only an authorized Knight Vigilant at the Temple of the Sword Vigilant may award a higher rank, to one character at a time for their own recognized rides; any area within the Temple is valid. Another character's rank or a completed party quest confers no personal rank. This is true world state. The order is public and proud, but distant NPCs need not know a character's rank unless shown the brooch, banner, reputation, or introduced by someone who does." })

