const lines = N.filter((n) => rk(n) >= 0).map((n) => { const i = rk(n); return n + ': ' + R[i] + (Q[i] ? ', ' + cr(n) + ' of ' + Q[i] + ' Hadrik-recognized thefts toward ' + R[i + 1] : ', ready for serious Guild work') })
effects.push({ type: 'story', instruction: 'IF a character asks about their Hand standing, answer for that character. Hand standing by character: ' + lines.join('; ') + '. Advancement requires bringing the take back to Hadrik, satisfying valid target, valid loot, and no unresolved heat, then receiving his explicit recognition; it is not granted by a stolen item alone. Disregard this instruction if no one is asking about Hand standing.' })

thieves_guild_rank_work_scope.script:
const CONTEXT=["Hand Credit Standing: 1", "Hand Credit Standing: 2", "Hand Credit Standing: 3", "Hand Credit Standing: 4"];
const R = ["Provisional Hand", "Working Hand", "Trusted Hand", "Guild-Recognized Hand"]
const Q = [1, 2, 3]
const T = check({ type: 'player-traits' }) || {}
const B = (storage.rankLedger && storage.rankLedger["thieves"]) || {}
const rk = (n) => { const l = T[n] || []; for (let i = R.length - 1; i >= 0; i--) if (l.includes(R[i])) return i; return -1 }
const COUNTS = [["Hand record (Provisional Hand): 0/1", "Hand record (Provisional Hand): 1/1"], ["Hand record (Working Hand): 0/2", "Hand record (Working Hand): 1/2", "Hand record (Working Hand): 2/2"], ["Hand record (Trusted Hand): 0/3", "Hand record (Trusted Hand): 1/3", "Hand record (Trusted Hand): 2/3", "Hand record (Trusted Hand): 3/3"], []]
const PENDING=["Hand Credit Pending", "Hand Credit Pending", "Hand Credit Pending", ""];
const cr = (n) => {const r=rk(n);return Math.min(Q[r]||0,Math.max(0,(COUNTS[r]||[]).findIndex(x=>(T[n]||[]).includes(x)))+(((T[n]||[]).includes(PENDING[r])&&(T[n]||[]).includes(CONTEXT[r]))?1:0))}
const N = Object.keys(T)
const at = (i) => N.filter((n) => rk(n) === i)
const ready = (i) => at(i).filter((n) => Q[i] && cr(n) >= Q[i])
const both = (l) => l.length > 1 ? l.slice(0, -1).join(', ') + ' and ' + l[l.length - 1] : (l[0] || '')
const location = check({ type: 'party-location' }) || ''
const area = check({ type: 'party-area' }) || ''
if (!(location === "Ardan's Watch" && ['The Dry Cistern', 'Old Town', 'The Basement'].includes(area))) { skip = true }
const G = ["The character is provisionally accepted but has not yet earned a recognized Hand theft. If work is requested, keep the first score local, concrete, worthwhile and potentially profitable, with clear security and a real way out; Kit and Hadrik can offer different methods, but Hadrik will later judge the returned take.", "The character is a Working Hand building a reputation through ordinary professional theft. If work is requested, keep it local or Basement-facing and vary burglary, robbery, social entry, fencing, and guard pressure.", "The character is a Trusted Hand whose work can now attract rival-Hand, corrupt-guard, and Syndicate complications. If work is requested, raise the security, consequences, value, and payment without making every job a campaign crisis.", "The Hand is Guild-recognized. If work is requested, it may involve serious Guild interests, rival Hands, Syndicate pressure, protection disputes, or the first concrete road toward a Seat at the Table. Keep the character's choices central."]
const byRank = {}
for (const n of N) { const i = rk(n); if (i >= 0) (byRank[i] = byRank[i] || []).push(n) }
const parts = Object.keys(byRank).map((i) => 'For ' + both(byRank[i]) + ' (' + R[i] + '): ' + G[i])
if (!parts.length) skip = true
if (!skip) effects.push({ type: 'story', instruction: parts.join(' ') })

