tavern_company_return_recognition.script:
const deeds = storage.companyDeeds || 0
const stage = storage.companyStage || 'new_house'
const headquarters = storage.companyHeadquartersImproved === true
storage.companyRecognitionPending = false

if (stage === 'new_house' && deeds >= 1) {
  storage.companyStage = 'known'
  effects.push({ type: 'quest-progress', questId: 'Make the Name Mean Something' })
  effects.push({ type: 'quest-init', operator: 'set', value: 'Build the Adventuring House' })
  effects.push({ type: 'story', instruction: 'Create a warm, interactive homecoming after the company’s first completed job. Payment, gratitude, witnesses, returned people, recovered proof, or local talk makes the deed tangible. People begin using the company name already established in the story; never invent a replacement. Establish the company as a name locals now know and make the request wall and central company table permanent. Offer a choice of a first substantial headquarters improvement—map room, bunks, armory, workshop, infirmary, stables or transport space, private meeting room, trophy display, or another practical facility—but do not choose for the company.' })
} else if ((stage === 'known' || stage === 'new_house') && deeds >= 3 && headquarters) {
  storage.companyStage = deeds >= 6 ? 'renowned' : 'established'
  effects.push({ type: 'quest-progress', questId: 'Build the Adventuring House' })
  effects.push({ type: 'quest-init', operator: 'set', value: 'Establish the Company' })
  if (deeds >= 6) {
    effects.push({ type: 'quest-progress', questId: 'Establish the Company' })
    effects.push({ type: 'quest-init', operator: 'set', value: 'Build a Renowned Company' })
    effects.push({ type: 'story', instruction: 'Create a major catch-up homecoming: the company’s completed deeds and established facility now make it regionally renowned. Clients and recruits travel specifically to this tavern. Offer a defining regional-scale commission and one meaningful further headquarters or transport improvement. The members still personally lead important work; delegation remains optional.' })
  } else {
    effects.push({ type: 'story', instruction: 'Create an earned established-company homecoming. Several clients know where to find the house, adventurers discuss joining, and one serious outside power offers an optional relationship: League affiliation, civic charter, guild or temple sponsorship, merchant-house backing, noble warrant, or continued independence with a valuable contact. Also surface one competent specialist applicant suited to the company’s demonstrated work. Do not assign a patron, charter, specialist, or recruit automatically.' })
  }
} else if (stage === 'known' && deeds >= 3 && !headquarters) {
  effects.push({ type: 'story', instruction: 'Create a concise homecoming that acknowledges the company has completed enough deeds to become established but has not yet chosen a substantial headquarters facility. Make that remaining choice clear and offer several practical improvements suited to the actual tavern without choosing one for the company. Do not advance the company to established standing yet.' })
} else if (stage === 'established' && deeds >= 6) {
  storage.companyStage = 'renowned'
  effects.push({ type: 'quest-progress', questId: 'Establish the Company' })
  effects.push({ type: 'quest-init', operator: 'set', value: 'Build a Renowned Company' })
  effects.push({ type: 'story', instruction: 'Create a major return establishing the adventuring house as regionally renowned. Clients and recruits now travel specifically to this tavern, and its facilities, companions, patrons or independence, rivals, trophies, and relationships are visible. Offer a defining regional-scale commission and a meaningful headquarters or transport improvement. The members still personally lead important field work; delegation remains optional.' })
} else {
  effects.push({ type: 'story', instruction: 'Create a concise company homecoming grounded in the completed job: payment or gratitude, the keeper’s report, crew and regular reactions, one consequence for reputation or relationships, and any lead naturally produced by the deed. Do not repeat a founding or promotion scene.' })
}

