blood_rank_work_scope.script:
const CONTEXT=["Company Credit Standing: 1", "Company Credit Standing: 2", "Company Credit Standing: 3", "Company Credit Standing: 4", "Company Credit Standing: 5"];
const R = ["Crimson Company Hired Blade", "Crimson Company Redblade", "Fledgling of the Blood", "Blooded", "Lord of the Blood"]
const Q = [3, 4, 4, 5]
const T = check({ type: 'player-traits' }) || {}
const B = (storage.rankLedger && storage.rankLedger["blood"]) || {}
const rk = (n) => { const l = T[n] || []; for (let i = R.length - 1; i >= 0; i--) if (l.includes(R[i])) return i; return -1 }
const COUNTS = [["Company record (Crimson Company Hired Blade): 0/3", "Company record (Crimson Company Hired Blade): 1/3", "Company record (Crimson Company Hired Blade): 2/3", "Company record (Crimson Company Hired Blade): 3/3"], ["Company record (Crimson Company Redblade): 0/4", "Company record (Crimson Company Redblade): 1/4", "Company record (Crimson Company Redblade): 2/4", "Company record (Crimson Company Redblade): 3/4", "Company record (Crimson Company Redblade): 4/4"], ["Company record (Fledgling of the Blood): 0/4", "Company record (Fledgling of the Blood): 1/4", "Company record (Fledgling of the Blood): 2/4", "Company record (Fledgling of the Blood): 3/4", "Company record (Fledgling of the Blood): 4/4"], ["Company record (Blooded): 0/5", "Company record (Blooded): 1/5", "Company record (Blooded): 2/5", "Company record (Blooded): 3/5", "Company record (Blooded): 4/5", "Company record (Blooded): 5/5"], []]
const PENDING=["Company Credit Pending", "Company Credit Pending", "Company Credit Pending", "Company Credit Pending", ""];
const cr = (n) => {const r=rk(n);return Math.min(Q[r]||0,Math.max(0,(COUNTS[r]||[]).findIndex(x=>(T[n]||[]).includes(x)))+(((T[n]||[]).includes(PENDING[r])&&(T[n]||[]).includes(CONTEXT[r]))?1:0))}
const N = Object.keys(T)
const at = (i) => N.filter((n) => rk(n) === i)
const ready = (i) => at(i).filter((n) => Q[i] && cr(n) >= Q[i])
const both = (l) => l.length > 1 ? l.slice(0, -1).join(', ') + ' and ' + l[l.length - 1] : (l[0] || '')
if (storage.inCompanySpace !== true) { skip = true }
const G = ["Outsiders on the writ, useful and watched. IF Company work is surfaced, keep it local, survivable, paid, and varied. Culls are the staple but no more than a third of it: strigoi on the terraces, ghouls in Charnel Mountain’s upper workings, a wolf pack on the pass road, something in a barrow nobody has opened since the Schism. The rest is people and searching: a lordless band out of a valley with no lord left, taking the pass road; a watchpost that stopped answering; a pressing crew that went up the high terraces and did not come down; a tincture wagon that never arrived. Each job should quietly teach one rule of this country — the levy, the truce, what silver does, what a stranger is worth here. Do not offer house-interior work, court business, or anything that assumes standing among vampires. Disregard this instruction if no Company work is being offered or discussed.", "Marked by the lord they serve so that no other vampire may feed on them. IF Company work is surfaced, it is the houses’ own business rather than valley work: carrying something between rivals under the Black Gate truce, finding out what House Vyrel is doing, bringing House Malren a specimen or a page intact, finding who is selling where a lord sleeps by day and getting there first, putting down a vampire made six weeks ago who cannot control it, hunting an old Company blade who turned and knows exactly how it is done, quiet problems a lord would rather not have in writing, and errands that put the party inside courts and estates. The pay is better and the failure is worse. Disregard this instruction if no Company work is being offered or discussed.", "Made vampires with a Company captaincy and soldiers under them. IF Company work is surfaced, it assumes command and it assumes night: leading Company blades on a cull or a raid, work that requires being somewhere no mortal could go or survive, standing for a lord where a mortal would not be listened to, and answering for what the soldiers do. The Company no longer issues them silver. Disregard this instruction if no Company work is being offered or discussed.", "They deal with the houses as principals. IF Company work is surfaced, it is house business at the top: the Ferals of the high wilds, whatever tries to come through the Black Gate, rivals moving against a lord, the Syndicate’s price for something, and anything touching the Vale Sable and what is still alive inside it. Work at this level creates enemies who answer back. Disregard this instruction if no Company work is being offered or discussed.", "They are a Lord of the Blood and hold a valley. Company work is theirs to commission, not to take."]
const byRank = {}
for (const n of N) { const i = rk(n); if (i >= 0) (byRank[i] = byRank[i] || []).push(n) }
const parts = Object.keys(byRank).map((i) => 'For ' + both(byRank[i]) + ' (' + R[i] + '): ' + G[i])
if (!parts.length) skip = true
if (!skip) effects.push({ type: 'story', instruction: 'IF Company work is surfaced: ' + parts.join(' ') + ' Disregard this instruction if no Company work is being offered or discussed.' })

