shop_stock_presentation.script:
const loc = check({ type: 'party-location' }) || ''
const area = check({ type: 'party-area' }) || ''
const place = loc + '||' + area
const marker = 'const data = '
const all = Object.values(triggers || {})
  .filter((t) => t && typeof t.name === 'string' && t.name.startsWith("shop_stock_data_") && typeof t.script === 'string')
  .flatMap((t) => { const at = t.script.indexOf(marker); return at < 0 ? [] : JSON.parse(t.script.slice(at + marker.length)) })
const here = all.filter((e) => e.place === place)
const present = (e) => !!e.keeper && check({ type: 'npc-in-scene', npc: e.keeper }) === true
const shop = here.find(present) || here.find((e) => !e.keeper) || here[0]
const priced = (lines) => lines.map((l) => l[0] + ', ' + l[1] + ' florins').join('; ')
if (shop) {
  const lines = ["A member of the party is shopping or selling here. This is what the shop has on its shelf right now and what it pays. When the party asks what is for sale, show only the goods that fit what they asked about, never more than four in one answer, each in its own short paragraph of plain prose with its exact name, its price in florins, and what it is for. Do not use headings, bold text, bullets, lists, or tables. Do not add shelf goods that are not listed here, and do not give any item powers beyond what its description says. The keeper talks like a trader, not a catalogue. When the party offers something for sale, the keeper pays within the buying rate below and says the amount plainly. If the party asks for shelf goods this shop does not list, the keeper says plainly they do not carry them and, if one fits, points to one of the other shops here named below. This covers what is on the shelf. It does not limit commissions or custom work, goods or deals the story or a character has already set up, fences and back-room trade, or services; handle those as the scene establishes. When a purchase or sale is agreed, end with one plain sentence saying who pays whom, how many florins, and what changes hands, using the exact item name, such as \"Durn pays Sef 14 florins and takes the Iron Helm.\" or \"Sef pays Durn 6 florins for the Iron Shortsword.\" Coins are put into the seller's hand, never left on a counter. Quote a price only for something actually for sale. This does not govern food, drink, or lodging."]
  if (shop.keeper) lines.push(present(shop) ? 'The keeper is ' + shop.keeper + '.' : shop.keeper + " is not here right now; a hand minds the stall and sells at the same prices.")
  lines.push('On the shelf: ' + priced(shop.sells || []) + '.')
  if ((shop.counter || []).length) lines.push('Behind the counter, shown only to a serious buyer who asks for better: ' + shop.counter.map((l) => l[0] + ', ' + l[1] + ' florins (' + (l[2] || '') + ')').join('; ') + '.')
  if (shop.members) {
    const held = check({ type: 'player-traits' }) || {}
    const names = Object.keys(held).filter((n) => (held[n] || []).some((x) => shop.members.traits.includes(x)))
    if (names.length) lines.push("Members' stock: this shop also sells to " + shop.members.label + ', so ' + names.join(' and ') + " may buy these as well: " + priced(shop.members.sells) + ". Sell these only to a member; anyone else is told plainly they are kept for members.")
  }
  if (shop.buys) lines.push('Buying rate: ' + shop.buys)
  const others = all.filter((e) => e !== shop && e.place.startsWith(loc + '||') && e.place !== place)
  if (others.length) lines.push('Other shops here: ' + others.map((e) => e.place.split('||')[1] + ' (' + e.kind + (e.keeper ? ', ' + e.keeper : '') + ')').join(', ') + '.')
  effects.push({ type: 'story', instruction: lines.join(' ') })
} else {
  const nearby = all.filter((e) => e.place.startsWith(loc + '||'))
  if (nearby.length) {
    const where = nearby.map((e) => e.place.split('||')[1] + (e.keeper ? ' (' + e.keeper + ')' : '')).join(', ')
    effects.push({ type: 'story', instruction: "A member of the party is shopping or selling where no shop is recorded. A trader who is in the scene, or whom the story or their own description establishes, carries ordinary goods by default at prices that agree with the worth of goods in this world, named plainly as they are, and may have one or two Fine pieces at Fine prices; anything more must already be established by the story or the trader's own description. Do not give any item powers beyond what its name says. This covers what is on the shelf. It does not limit commissions or custom work, goods or deals the story or a character has already set up, fences and back-room trade, or services; handle those as the scene establishes. When a purchase or sale is agreed, end with one plain sentence saying who pays whom, how many florins, and what changes hands, using the exact item name, such as \"Durn pays Sef 14 florins and takes the Iron Helm.\" or \"Sef pays Durn 6 florins for the Iron Shortsword.\" Coins are put into the seller's hand, never left on a counter. Quote a price only for something actually for sale. This does not govern food, drink, or lodging. If the party is looking for a shop, say plainly where trade is done here: " + where + '.' })
  } else {
    effects.push({ type: 'story', instruction: "A member of the party is shopping or selling where no shop is recorded. A trader who is in the scene, or whom the story or their own description establishes, carries ordinary goods by default at prices that agree with the worth of goods in this world, named plainly as they are, and may have one or two Fine pieces at Fine prices; anything more must already be established by the story or the trader's own description. Do not give any item powers beyond what its name says. This covers what is on the shelf. It does not limit commissions or custom work, goods or deals the story or a character has already set up, fences and back-room trade, or services; handle those as the scene establishes. When a purchase or sale is agreed, end with one plain sentence saying who pays whom, how many florins, and what changes hands, using the exact item name, such as \"Durn pays Sef 14 florins and takes the Iron Helm.\" or \"Sef pays Durn 6 florins for the Iron Shortsword.\" Coins are put into the seller's hand, never left on a counter. Quote a price only for something actually for sale. This does not govern food, drink, or lodging." })
  }
}

