offer_pool_league.script:
const location = check({ type: 'party-location' }) || ''
const area = check({ type: 'party-area' }) || ''
const region = check({ type: 'party-region' }) || ''
const spaces = ["Ardan's Watch||Watchtower - League Hall", "Tevantia||Tevantia League Chapterhouse", "Coriva||The Coriva League Chapterhouse", "Warmwater Township||The Watch-Hall", "Oasis||The League Chapterhouse", "Drusavia||The League Chapterhouse", "Sanctuary||The League Chapterhouse", "Dun Solas||The League Chapterhouse", "Durg Sthira||The League Chapterhouse", "Carendon||The Wildward House", "Gorren Crossing||The House of Many Banners", "Oasis||Sky-River House", "Cloudtop||Skygate House"]
