warmwater_aurora_rumor.script:
storage.warmwaterTurns = (storage.warmwaterTurns || 0) + 1
let o = storage.warmwaterAurora
if (!o) {
  let at = 4 + Math.floor(Math.random() * 17)
  o = storage.warmwaterAurora = { turns: 0, at, open: -1, told: false }
}
o.turns += 1
if (o.told || o.turns < o.at) { skip = true } else {
  o.told = true
  o.open = o.turns
  effects.push({ type: 'story', instruction: "If it fits the scene, have someone mention in passing that the lights are coming: an aurora night is near, and Warmwater will throw the Aurora Ball in the Ice Gardens, as it does when the aurora burns and the Widow of Winter walks the ice. Mention it once and move on; the party can go if they want to." })
}

