gather_forage.script:
const ACTIVITY = "forage"
const COOLDOWN = 15
const loc = check({ type: 'party-location' }) || ''
const area = check({ type: 'party-area' }) || ''
const region = check({ type: 'party-region' }) || ''
const tick = check({ type: 'game-tick' }) || 0
const marker = 'const data = '
const all = Object.values(triggers || {})
  .filter((t) => t && typeof t.name === 'string' && t.name.startsWith("material_pool_data_") && typeof t.script === 'string')
  .flatMap((t) => { const at = t.script.indexOf(marker); return at < 0 ? [] : JSON.parse(t.script.slice(at + marker.length)) })
const here = all.filter((e) => e.region === region && e.activity === ACTIVITY)
const entry = here.find((e) => e.where === loc + '||' + area) || here.find((e) => e.where === loc) || here.find((e) => e.where === '')
storage.gathering = storage.gathering || {}
const mem = storage.gathering[ACTIVITY] = storage.gathering[ACTIVITY] || { loc: '', spots: {} }
if (mem.loc !== loc) { mem.loc = loc; mem.spots = {} }
const spot = loc + '||' + area
const list = (names) => names.join(', ')
if (!entry) {
  const place = (w) => { const [l, a] = w.split('||'); return a ? a + ' in ' + l : l }
  const elsewhere = [...new Set(here.map((e) => e.where).filter((w) => w && w !== spot && w !== loc))].map(place)
  effects.push({ type: 'story', instruction: "There is nothing worth foraging for at this spot, whatever the roll. Say so plainly in the story with a concrete reason the ground offers nothing. Do not name any item or write any count of items this turn." + (elsewhere.length ? ' Also say plainly in the story that it can be done at ' + list(elsewhere) + '.' : '') + " End with one plain sentence in which the character takes nothing, such as \"Brann takes nothing.\"" })
} else if (mem.spots[spot] !== undefined && tick - mem.spots[spot] < COOLDOWN) {
  effects.push({ type: 'story', instruction: "The party has already worked this spot and it is picked clean for now, whatever the roll. Describe only that the ground is stripped; the party can come back later or try somewhere else. Do not describe cutting, picking, or taking anything this turn, and do not name any item or write any count of items. End with one plain sentence in which the character takes nothing, such as \"Brann takes nothing.\"" })
} else {
  mem.spots[spot] = tick
  const lines = ["A member of the party is foraging here. This is what this ground can give; it is an offer, and the party chooses what to take."]
  lines.push((entry.everyday || []).length ? 'Everyday find: ' + list(entry.everyday) + '.' : 'There is no everyday find here.')
  if ((entry.better || []).length) lines.push('Better find: ' + list(entry.better) + '.')
  else if ((entry.everyday || []).length && !(entry.earned || []).length) lines.push("There is no better find here; a great roll only means more of the everyday find, never another material.")
  if (entry.note) lines.push(entry.note)
  if ((entry.earned || []).length) lines.push('If the story has already shown that ' + entry.earnedWhen + ', this ground also gives: ' + list(entry.earned) + '.')
  lines.push("The roll decides the find, in these amounts. Failure or critical failure: nothing worth keeping. Mixed results: 1 of the everyday find. Basic success: 1 or 2. Success: exactly 2 or 3. Great success: 3 or 4, and the better find if there is one. Critical success: 4, and the better find if there is one. Never more than 4 of the everyday find in one attempt. Below a great success, do not mention the better find at all. If no roll was made, treat it as a basic success.")
  lines.push("End the gathering with one plain sentence in which the character who gathered takes the finds, using the exact item names written here with a number, such as \"Brann takes 3 Healing Herbs.\" with that character's name. After a failure, write that the character takes nothing, such as \"Brann takes nothing.\" Only the items named here may appear in that sentence or be counted anywhere in the story; any other plant, part, or stone is scenery, described with no item name and no count.")
  effects.push({ type: 'story', instruction: lines.join(' ') })
}

