gather_harvest_creature.script:
const PARTS = {"beast": {"type": "beast", "everyday": ["Rawhide", "Game Meat"], "note": "Any animal worth skinning gives a hide and meat; a bird or small animal gives only Game Meat. A dire beast or monstrous predator gives a hide big enough for armor."}, "venomous beast": {"type": "venomous beast", "everyday": ["Venom Gland"], "better": ["Spider Silk"], "note": "Giant spiders also give silk from the spinnerets and the web; scorpions and plague-beasts give only the gland."}, "draconic kin": {"type": "draconic kin", "everyday": ["Drake Scale"], "better": ["Acid Gland"], "note": "Every drake gives scale. Only acid-spitting drakes give an acid gland. Ice drakes of the far north also give Rimebone."}, "aquatic creature": {"type": "aquatic creature", "everyday": ["Rawhide"], "better": ["Venom Gland"], "note": "Giant crocodiles and sea serpents give armor-grade hide; reef serpents also give a venom gland."}, "giant-kin": {"type": "giant-kin", "everyday": [], "better": ["Troll Blood"], "note": "Only trolls give anything worth taking, and their blood must be bottled before the wounds close."}, "fire elemental": {"type": "fire elemental", "everyday": ["Emberglass"], "better": ["Elemental Core"], "note": "A broken fire elemental leaves emberglass where it burned hottest; only a strong one leaves a core."}, "storm elemental": {"type": "storm elemental", "everyday": ["Thunderglass"], "better": ["Elemental Core"], "note": "A storm elemental fuses thunderglass where it struck; only a strong one leaves a core."}, "frost elemental": {"type": "frost elemental", "everyday": ["Frostjade"], "better": ["Elemental Core"], "note": "A frost elemental leaves frostjade at its heart; only a strong one leaves a core."}, "water elemental": {"type": "water elemental", "everyday": [], "better": ["Elemental Core"], "note": "A water elemental leaves nothing but water unless it was strong enough to leave a core."}, "construct": {"type": "construct", "everyday": ["Mechanical Components"], "better": ["Elemental Core"], "note": "A broken construct gives workable parts; only one driven by a bound power gives a core."}, "stone construct": {"type": "stone construct", "everyday": [], "better": ["Elemental Core"], "note": "A stone guardian is rubble when broken, except for the core of a true golem."}, "shadow creature": {"type": "shadow creature", "everyday": [], "better": ["Voidglass"], "note": "Most shadow things leave nothing. A strong one leaves a shard of voidglass where it came apart."}, "deep-thing": {"type": "deep-thing", "everyday": ["Venom Gland"], "better": ["Acid Gland"], "note": "Gricks and ropers give venom; a purple worm gives the acid gland of its gut."}, "plant creature": {"type": "plant creature", "everyday": ["Healing Herbs"], "better": ["Witchwood"], "note": "Fungi and vines give herbs worth drying; a vegetation monster grown around old magic gives witchwood."}}
const typesByNPC = check({ type: 'npc-type', npc: 'anySceneNPC' }) || {}
const present = [...new Set(Object.values(typesByNPC).filter((t) => PARTS[t]))]
const rows = present.length ? present.map((t) => PARTS[t]) : Object.values(PARTS)
const list = (names) => names.join(', ')
const describe = (p) => p.type + ": " + [
  (p.everyday || []).length ? 'everyday find ' + list(p.everyday) : 'no everyday find',
  (p.better || []).length ? 'better find ' + list(p.better) : '',
].filter(Boolean).join('; ') + '. ' + (p.note || '')
const lines = ["A member of the party is harvesting a creature's body. A body gives its parts once. This is what the creature types here can give."]
for (const p of rows) lines.push(describe(p))
lines.push("These creature types give nothing worth harvesting: aberration, corporeal undead, spectral undead, undead spellcaster, fey, fiend, armored fiend, celestial, ooze, cursed, dragon. People are searched for their belongings, not butchered; harvesting a person gives nothing.")
lines.push("The roll decides how cleanly the parts come away. Failure or critical failure: the parts are spoiled and nothing worth keeping comes away. Mixed results or basic success: 1 of the everyday find. Success or better: 1 of each everyday find, or 2 from a large creature. A better find comes only from the kind of creature its note names, or from a strong, elite, or named creature, and only on a success or better. If no roll was made, treat it as a basic success.")
lines.push("End the harvest with one plain sentence in which the character who did the harvesting takes the parts, using the exact item names written here with a number, such as \"Brann takes 1 Rawhide and 1 Game Meat.\" with that character's name. After a failure, write that the character takes nothing, such as \"Brann takes nothing.\" Only the items named here may appear in that sentence or be counted anywhere in the story; any other part of the body is scenery, described with no item name and no count.")
effects.push({ type: 'story', instruction: lines.join(' ') })

