house_restore_request.script:
const homes = {"Carendon": {"area": "The Wildward House", "veteran": "Hugh Merrivant"}, "Gorren Crossing": {"area": "The House of Many Banners", "veteran": "Tula Vereskar"}, "Oasis": {"area": "Sky-River House", "veteran": "Calia Delassar"}, "Cloudtop": {"area": "Skygate House", "veteran": "Rielle Mazarane"}}
const location = check({ type: 'party-location' }) || ''
