  storage.housePathInitialized = true
  storage.adventuringHouse = { active: true, homeLocation: location, homeArea: area, veteran: home.veteran, stage: 'proving', deedCredits: 0, totalDeeds: 0, lastCreditTick: -999 }
  storage.housePathActive = true
  storage.atHouseHome = true
  storage.houseStage = 'proving'
  storage.houseDeedCredits = 0
  storage.houseTotalDeeds = 0
