  storage.houseRecognitionPendingTick = -999
  if (!['available', 'accepted', 'completed'].includes(check({ type: 'quest-status', questId: "Raise the Standard" }))) effects.push({ type: 'quest-init', operator: 'set', value: "Raise the Standard" })
