offer_pool_guild_of_all_arts.script:
const location = check({ type: 'party-location' }) || ''
const area = check({ type: 'party-area' }) || ''
const region = check({ type: 'party-region' }) || ''
const spaces = ["Forge-town||The Guild of All Arts"]
if (!spaces.includes(location + '||' + area)) { skip = true }
if (!skip) {
  const rankTraits = ["Guild Apprentice", "Guild Journeyman", "Guild Artisan", "Master of the Guild"]
  const poolRanks = ["apprentice", "journeyman", "artisan", "master"]
  const traitsByCharacter = check({ type: 'player-traits' }) || {}
  let rankIndex = -1
  for (const list of Object.values(traitsByCharacter)) {
    let i = rankTraits.length - 1
    const holds = (t) => Array.isArray(t) ? t.some((x) => list.includes(x)) : list.includes(t)
    while (i >= 0 && !holds(rankTraits[i])) i--
    if (i < 0) continue
    const own = Math.max(0, i)
    rankIndex = rankIndex < 0 ? own : Math.min(rankIndex, own)
  }
  let rankAt = Math.min(Math.max(0, rankIndex), poolRanks.length - 1)
  const dataPrefix = "offer_pool_guild_of_all_arts_data_"
  const marker = 'const data = '
  const all = Object.values(triggers || {})
    .filter((t) => t && typeof t.name === 'string' && t.name.startsWith(dataPrefix) && typeof t.script === 'string')
    .flatMap((t) => { const at = t.script.indexOf(marker); return at < 0 ? [] : JSON.parse(t.script.slice(at + marker.length)) })
    .filter((e) => e.region === region)
  const slots = ["any", "any", "any"]
  let eligible = []
  while (rankAt >= 0) {
    eligible = all.filter((e) => e.rank === poolRanks[rankAt])
    if (eligible.length >= slots.length) break
    rankAt--
  }
  if (eligible.length < slots.length) {
    skip = true
  } else {
    storage.offerPools = storage.offerPools || {}
    const memory = storage.offerPools["guild-of-all-arts"] = storage.offerPools["guild-of-all-arts"] || { recent: [] }
    const picks = []
    const pickFrom = (list) => list[Math.floor(Math.random() * list.length)]
    for (const slot of slots) {
      const open = eligible.filter((e) => !picks.includes(e) && (slot === 'any' || e.kind === slot))
      const fits = open
      const fresh = fits.filter((e) => !memory.recent.includes(e.id))
      const choice = pickFrom(fresh.length > 0 ? fresh : fits)
      if (choice) picks.push(choice)
    }
    memory.recent = memory.recent.concat(picks.map((e) => e.id)).slice(-12)
    const framing = "The commission board of the Guild of All Arts holds these three commissions right now. When the party reads the board or asks for a commission, present exactly these three as separate postings in plain in-fiction prose, as a Guild clerk or a passing member would point them out. Keep each commission's client, what is to be made, the hint about materials and where to work, where it is handed over and the reward; invent fresh names for any people described only by role, and bring the people sketched to life as described. Anyone may take the work for its pay; it counts toward a member's standing in the Guild when the finished piece is handed to the client in person. Do not replace them with other work or add more, and do not assume the party accepts any of them. If a posting names someone who has died, left, or can no longer help, someone close to them or to the place brings the same work instead; never bring a character back or move them to fit a posting."
    effects.push({ type: 'story', instruction: framing + '\n\n' + picks.map((e, n) => (n + 1) + '. ' + e.text).join('\n\n') })
  }
}

