academy_event_cleanup.script:
const tick = check({ type: 'game-tick' })
const seen = storage.academyEventSeen = storage.academyEventSeen || {}
const last = storage.academyEventLast = storage.academyEventLast || {}
const missions = storage.academyMissions = storage.academyMissions || {}
let any = false
for (let k = 0; k < 4; k++) {
  if (!storage['academyEventDone' + k]) continue
  any = true
  if (typeof seen[k] !== 'number') { seen[k] = tick; continue }
  if (tick > seen[k]) { storage['academyEventDone' + k] = false; delete seen[k]; last[k] = tick; if (missions[k] && missions[k].done) delete missions[k] }
}
if (!any) skip = true

