offer_pool_tarnholme.script:
const location = check({ type: 'party-location' }) || ''
const area = check({ type: 'party-area' }) || ''
const region = check({ type: 'party-region' }) || ''
const spaces = ["The Main Island||The Great Hall"]
if (!spaces.includes(location + '||' + area)) { skip = true }
if (!skip) {
  const rankTraits = ["First-Year Student", "Second-Year Student", "Third-Year Student", "Fourth-Year Student", "Tarnholme Graduate"]
  const poolRanks = ["first", "second", "third", "fourth"]
  const traitsByCharacter = check({ type: 'player-traits' }) || {}
  let rankIndex = -1
  for (const list of Object.values(traitsByCharacter)) {
    let i = rankTraits.length - 1
    const holds = (t) => Array.isArray(t) ? t.some((x) => list.includes(x)) : list.includes(t)
    while (i >= 0 && !holds(rankTraits[i])) i--
    if (i < 0) continue
    const own = Math.max(0, i)
    rankIndex = rankIndex < 0 ? own : Math.min(rankIndex, own)
  }
  let rankAt = Math.min(Math.max(0, rankIndex), poolRanks.length - 1)
  const dataPrefix = "offer_pool_tarnholme_data_"
  const marker = 'const data = '
  const all = Object.values(triggers || {})
    .filter((t) => t && typeof t.name === 'string' && t.name.startsWith(dataPrefix) && typeof t.script === 'string')
    .flatMap((t) => { const at = t.script.indexOf(marker); return at < 0 ? [] : JSON.parse(t.script.slice(at + marker.length)) })
    .filter((e) => e.region === region)
  const slots = ["combat", "investigation", "social"]
  let eligible = []
  while (rankAt >= 0) {
    eligible = all.filter((e) => e.rank === poolRanks[rankAt])
    if (eligible.length >= slots.length) break
    rankAt--
  }
  if (eligible.length < slots.length) {
    skip = true
  } else {
    storage.offerPools = storage.offerPools || {}
    const memory = storage.offerPools["tarnholme"] = storage.offerPools["tarnholme"] || { recent: [] }
    const picks = []
    const pickFrom = (list) => list[Math.floor(Math.random() * list.length)]
    for (const slot of slots) {
      const open = eligible.filter((e) => !picks.includes(e) && (slot === 'any' || e.kind === slot))
      const fits = open
      const fresh = fits.filter((e) => !memory.recent.includes(e.id))
      const choice = pickFrom(fresh.length > 0 ? fresh : fits)
      if (choice) picks.push(choice)
    }
    memory.recent = memory.recent.concat(picks.map((e) => e.id)).slice(-9)
    const framing = "The Practica board in the Great Hall holds these three postings for the party's Year right now. When the party reads the board or asks for work, present exactly these three as separate postings in plain in-fiction prose; Wes Carrick, the Practica master, or students around the board may point them out. Keep each posting's situation, place and reward; invent fresh names for anyone the posting describes only by role, and bring the people it sketches to life as described. Do not replace them with other work or add more, and do not assume the party takes any. If a posting names someone who has died, left, or can no longer help, someone close to them or to the place brings the same work instead; never bring a character back or move them to fit a posting."
    effects.push({ type: 'story', instruction: framing + '\n\n' + picks.map((e, n) => (n + 1) + '. ' + e.text).join('\n\n') })
  }
}

fight_tracker.script:
const inCombat = check({ type: 'npc-in-combat', npc: 'anySceneNPC' })
const fighting = typeof inCombat === 'boolean'
  ? inCombat
  : !!inCombat && typeof inCombat === 'object' && Object.values(inCombat).some((v) => v === true)
storage.fightJustEnded = false
if (fighting) {
  if (storage.fightActive !== true) {
    storage.fightActive = true
    storage.fightTurn = 0
  }
  storage.fightTurn = (Number(storage.fightTurn) || 0) + 1
  storage.fightQuietTurns = 0
} else if (storage.fightActive === true) {
  storage.fightQuietTurns = (Number(storage.fightQuietTurns) || 0) + 1
  if (storage.fightQuietTurns >= 2) {
    storage.fightActive = false
    storage.fightTurn = 0
    storage.fightQuietTurns = 0
    storage.fightJustEnded = true
  } else {
    storage.fightTurn = (Number(storage.fightTurn) || 0) + 1
  }
} else {
  storage.fightActive = false
  storage.fightTurn = 0
  storage.fightQuietTurns = 0
}

