silver_sword_event_cleanup.script:
const tick = check({ type: 'game-tick' })
const seen = storage.silverSwordEventSeen = storage.silverSwordEventSeen || {}
const last = storage.silverSwordEventLast = storage.silverSwordEventLast || {}
let any = false
for (const k of [0]) {
  if (!storage['silverSwordEventDone' + k]) continue
  any = true
