silver_sword_hunt_approach.script:
const SETTLEMENTS = ["Vaudania", "Argenval", "Carendon", "Houndsditch", "Ducal Hill"]
const R = ["Initiate of the Silver Sword", "Silverblade", "Veteran Silverblade", "Master of the Hunt"]
const KEYS = ["initiate", "silverblade", "veteran", "master"]
const here = check({ type: 'party-location' }) || ''
const tick = check({ type: 'game-tick' })
const st = storage.silverSwordApproach = storage.silverSwordApproach || { visit: 0, last: '', shownVisit: -1, shownTick: -999, pending: null }
if (here !== st.last) { st.last = here; st.visit += 1; st.pending = null }
if (!SETTLEMENTS.includes(here) || st.shownVisit === st.visit || tick - st.shownTick < 30) { skip = true } else {
  if (!st.pending) {
    const T = check({ type: 'player-traits' }) || {}
    let rank = -1
    for (const l of Object.values(T)) { let i = R.length - 1; while (i >= 0 && !l.includes(R[i])) i--; if (i >= 0) rank = rank < 0 ? i : Math.min(rank, i) }
    const marker = 'const data = '
    const pool = Object.values(triggers || {})
      .filter((t) => t && typeof t.name === 'string' && t.name.startsWith("offer_pool_silver_sword_data_") && typeof t.script === 'string')
      .flatMap((t) => { const at = t.script.indexOf(marker); return at < 0 ? [] : JSON.parse(t.script.slice(at + marker.length)) })
    const memory = ((storage.offerPools = storage.offerPools || {})['silver-sword'] = storage.offerPools['silver-sword'] || { recent: [] })
    let options = []
    for (let r = Math.max(0, rank); r >= 0 && !options.length; r--) options = pool.filter((e) => e.rank === KEYS[r])
    const fresh = options.filter((e) => !memory.recent.includes(e.id))
    const near = fresh.filter((e) => e.location === here)
    const from = near.length ? near : fresh.length ? fresh : options
    const choice = from[Math.floor(Math.random() * from.length)]
    if (choice) {
      st.pending = { id: choice.id, text: choice.text, location: choice.location }
      memory.recent = memory.recent.concat([choice.id]).slice(-12)
    }
  }
  if (st.pending) effects.push({ type: 'narrative-event-start', eventId: "silver_sword_word_of_a_hunt" })
  else skip = true
}

