}

offer_pool_silver_sword.script:
const location = check({ type: 'party-location' }) || ''
const area = check({ type: 'party-area' }) || ''
const region = check({ type: 'party-region' }) || ''
const spaces = ["Castle Harstone||The Muster", "Castle Harstone||The Great Hall", "Castle Harstone||The Trials Yard", "Castle Harstone||The Grandmaster's Tower"]
if (!spaces.includes(location + '||' + area)) { skip = true }
if (!skip) {
  const rankTraits = ["Initiate of the Silver Sword", "Silverblade", "Veteran Silverblade", "Master of the Hunt"]
  const poolRanks = ["initiate", "silverblade", "veteran", "master"]
  const traitsByCharacter = check({ type: 'player-traits' }) || {}
  let rankIndex = -1
  for (const list of Object.values(traitsByCharacter)) {
    let i = rankTraits.length - 1
    const holds = (t) => Array.isArray(t) ? t.some((x) => list.includes(x)) : list.includes(t)
    while (i >= 0 && !holds(rankTraits[i])) i--
    if (i < 0) continue
    const own = Math.max(0, i)
    rankIndex = rankIndex < 0 ? own : Math.min(rankIndex, own)
  }
  let rankAt = Math.min(Math.max(0, rankIndex), poolRanks.length - 1)
  const dataPrefix = "offer_pool_silver_sword_data_"
  const marker = 'const data = '
  const all = Object.values(triggers || {})
    .filter((t) => t && typeof t.name === 'string' && t.name.startsWith(dataPrefix) && typeof t.script === 'string')
    .flatMap((t) => { const at = t.script.indexOf(marker); return at < 0 ? [] : JSON.parse(t.script.slice(at + marker.length)) })
    .filter((e) => e.region === region)
  const slots = ["any", "any", "any"]
  let eligible = []
  while (rankAt >= 0) {
    eligible = all.filter((e) => e.rank === poolRanks[rankAt])
    if (eligible.length >= slots.length) break
    rankAt--
  }
  if (eligible.length < slots.length) {
    skip = true
  } else {
    storage.offerPools = storage.offerPools || {}
    const memory = storage.offerPools["silver-sword"] = storage.offerPools["silver-sword"] || { recent: [] }
    const picks = []
    const pickFrom = (list) => list[Math.floor(Math.random() * list.length)]
    for (const slot of slots) {
      const open = eligible.filter((e) => !picks.includes(e) && (slot === 'any' || e.kind === slot))
      const newKind = open.filter((e) => !picks.some((p) => p.kind === e.kind))
      const fits = slot === 'any' && newKind.length > 0 ? newKind : open
      const fresh = fits.filter((e) => !memory.recent.includes(e.id))
      const choice = pickFrom(fresh.length > 0 ? fresh : fits)
      if (choice) picks.push(choice)
    }
    memory.recent = memory.recent.concat(picks.map((e) => e.id)).slice(-12)
    const framing = "The Muster board at Castle Harstone holds these three hunts for the party's Order rank right now. When the party reads the board or asks for Order work, present exactly these three as separate postings in plain in-fiction prose; the quartermaster or hunters nearby may point them out, or, elsewhere in the castle, send the party to the board. Keep each posting's situation, place and reward; invent fresh names for anyone it describes only by role, and bring the people it sketches to life as described. A hidden truth in brackets is for you alone: never read it out or hint at it in the posting, and let it come out only through the hunt. For an Initiate, each hunt is offered as their supervised trial: a Veteran of the Order goes along to watch, advise and stand behind them, never to lead. Do not replace these with other work or add more, and do not assume the party takes any. If a posting names someone who has died, left, or can no longer help, someone close to them or to the place brings the same work instead; never bring a character back or move them to fit a posting."
    effects.push({ type: 'story', instruction: framing + '\n\n' + picks.map((e, n) => (n + 1) + '. ' + e.text).join('\n\n') })
  }
}

land_agent_listings.script:
const marker = 'const data = '
const src = Object.values(triggers || {}).find((t) => t && t.name === "land_agent_data")
const all = src ? JSON.parse(src.script.slice(src.script.indexOf(marker) + marker.length)) : []
storage.landAgent = storage.landAgent || {}
const m = storage.landAgent
m.recent = m.recent || []; m.listing = m.listing || []; m.sold = m.sold || []; m.owned = m.owned || []
if (Array.isArray(m.pending) || !m.pending) m.pending = {}
const kinds = ['town', 'country', 'estate']
const picks = []
for (const kind of kinds) {
  const open = all.filter((e) => e.kind === kind && !m.sold.includes(e.name) && !(e.name in m.pending))
  const fresh = open.filter((e) => !m.recent.includes(e.name))
  const list = fresh.length > 0 ? fresh : open
  if (list.length > 0) picks.push(list[Math.floor(Math.random() * list.length)])
}
m.listing = picks.map((e) => e.name)
m.recent = m.recent.concat(m.listing).slice(-6)
const show = (e) => '**' + e.name + '** (' + (e.kind === 'town' ? 'a town house ' + e.where + ', here in Ardan\'s Watch' : e.where) + '), ' + e.price.toLocaleString('en-US') + ' florins: ' + e.charm + '. The catch: ' + e.flaw + '.'
effects.push({ type: 'story', instruction: "Chessapie Bellwether, the land agent at Bellwether's Land Office just off the Way of Coin, is the one selling. She talks up every property's charms and is always frank about its one catch. The party is asking about property. She has exactly these properties on her books right now; present them as separate listings in plain in-fiction prose, with each one's name, where it is, its price, its charm and its catch. These are properties for sale, not jobs: do not offer any of them as a task or quest, and do not assume the party buys one. Prices are firm. If the party has bought from her before, she remembers." + '\n\n' + (picks.length > 0 ? picks.map(show).join('\n\n') : 'Nothing at all: everything on her books has sold.') + (Object.keys(m.pending).length > 0 ? '\n\nAlready bought by this party but not yet claimed: ' + Object.keys(m.pending).join(', ') + '. She reminds them, and offers again the job of going to take possession of the first of these.' : '') })

land_agent_purchase.script:
const marker = 'const data = '
const src = Object.values(triggers || {}).find((t) => t && t.name === "land_agent_data")
const all = src ? JSON.parse(src.script.slice(src.script.indexOf(marker) + marker.length)) : []
storage.landAgent = storage.landAgent || {}
const m = storage.landAgent
m.recent = m.recent || []; m.listing = m.listing || []; m.sold = m.sold || []; m.owned = m.owned || []
if (Array.isArray(m.pending) || !m.pending) m.pending = {}
const said = [].concat(check({ type: 'action' }) || []).join(' ').toLowerCase()
const listed = all.filter((e) => m.listing.includes(e.name))
const hit = (e) => said.includes(e.name.toLowerCase()) || e.keys.some((k) => said.includes(k))
const unsold = all.filter((e) => !m.sold.includes(e.name))
const byName = unsold.filter((e) => said.includes(e.name.toLowerCase()))
const named = byName.length > 0 ? byName : listed.filter(hit).length > 0 ? listed.filter(hit) : unsold.filter(hit)
const chosen = named.length === 1 ? named : listed
const open = Object.keys(m.pending).filter((n) => !named.some((e) => e.name === n))
if (listed.length === 0 && named.length === 0) { skip = true } else {
  const claim = (e) => e.kind === 'town'
    ? 'If it is ' + e.name + ' (' + e.price + ' florins): the job she offers is only to go and take possession of ' + e.name + ', a house ' + e.where + ' here in Ardan\'s Watch that the party has not seen yet. She mentions the catch as something waiting there, not as part of the job: ' + e.flaw + '.'
    : 'If it is ' + e.name + ' (' + e.price + ' florins): the job she offers is only to ride out to ' + e.name + ', ' + e.where + ', a new place the party has not been to, and take possession of it. She mentions the catch as something waiting there, not as part of the job: ' + e.flaw + '.'
  const tick = check({ type: 'game-tick' }) || 0
  if (named.length === 1) m.pending[named[0].name] = tick
  effects.push({ type: 'story', instruction: "The player is buying a property from Chessapie Bellwether at Bellwether's Land Office. The sale goes through only if the buyer pays the full price now; prices are firm. If they can't pay it, there is no sale and nothing more: she is gracious and keeps the listing open, and she does not offer a claim. If they pay, narrate the coin changing hands, then she hands over the deed and the keys and offers them the job of claiming it, which they may accept now or later. Say the property's name exactly as written and make clear it is theirs to go and claim. " + (chosen.length === 1 ? '' : 'Use the one the player chose:\n') + chosen.map(claim).join('\n') + (open.length > 0 ? '\nThe party already bought ' + open.join(', ') + ' and has not claimed it yet: she says that claim comes first, and offers this new claim only once that one is done.' : '') })
  effects.push({ type: 'write-boolean', key: 'landAgentSold', operator: 'set', value: true })
}

land_agent_home.script:
const marker = 'const data = '
const src = Object.values(triggers || {}).find((t) => t && t.name === "land_agent_data")
const all = src ? JSON.parse(src.script.slice(src.script.indexOf(marker) + marker.length)) : []
storage.landAgent = storage.landAgent || {}
const m = storage.landAgent
m.recent = m.recent || []; m.listing = m.listing || []; m.sold = m.sold || []; m.owned = m.owned || []
if (Array.isArray(m.pending) || !m.pending) m.pending = {}
const tick = check({ type: 'game-tick' }) || 0
for (const e of all) if (e.kind !== 'town' && !m.sold.includes(e.name) && check({ type: 'known-entity', entity: e.name })) m.sold.push(e.name)
for (const n of Object.keys(m.pending)) if (m.sold.includes(n) || tick - m.pending[n] > 40) delete m.pending[n]
const location = check({ type: 'party-location' }) || ''
const area = check({ type: 'party-area' }) || ''
const here = all.filter((e) => e.kind === 'town' || m.sold.includes(e.name)).find((e) => e.kind === 'town' ? location === "Ardan's Watch" && area.indexOf(e.name) === 0 : location === e.name)
if (!here) { m.at = ''; skip = true }
else if (m.at === here.name) { skip = true }
else {
  m.at = here.name
  const first = !m.owned.includes(here.name)
  const rested = (m.restedAt || {})[here.name]
  const canRest = !first && (rested === undefined || tick - rested >= 10)
  if (first) { m.owned.push(here.name); if (!m.sold.includes(here.name)) m.sold.push(here.name); delete m.pending[here.name] }
  if (first || canRest) {
    effects.push({ type: 'story', instruction: first
      ? 'This is ' + here.name + ', the party\'s own property, bought from Chessapie Bellwether at Bellwether\'s Land Office. The keys fit. Show it as theirs: ' + here.charm + '. The catch is still here to be dealt with: ' + here.flaw + '.'
      : 'The party is home at ' + here.name + ', their own property. They can rest here in safety and comfort; show a small sign of the place being lived in.' })
  }
  if (canRest) {
    m.restedAt = Object.assign({}, m.restedAt, { [here.name]: tick })
    for (const resource of ['health', 'mana', 'stamina']) effects.push({ type: 'player-resource', target: 'allPlayers', resource, operator: 'add', value: 9999 })
  }
  if (!first && !canRest) skip = true
}

offer_pool_legends.script:
const location = check({ type: 'party-location' }) || ''
const area = check({ type: 'party-area' }) || ''
const region = check({ type: 'party-region' }) || ''
const spaces = ["Ardan's Watch||Watchtower - League Hall"]
if (!spaces.includes(location + '||' + area)) { skip = true }
if (!skip) {
  const rankTraits = []
  const poolRanks = ["legend"]
  const traitsByCharacter = check({ type: 'player-traits' }) || {}
  let rankIndex = -1
  for (const list of Object.values(traitsByCharacter)) {
    let i = rankTraits.length - 1
    const holds = (t) => Array.isArray(t) ? t.some((x) => list.includes(x)) : list.includes(t)
    while (i >= 0 && !holds(rankTraits[i])) i--
    const own = Math.max(0, i)
    rankIndex = rankIndex < 0 ? own : Math.min(rankIndex, own)
  }
  let rankAt = Math.min(Math.max(0, rankIndex), poolRanks.length - 1)
  const dataPrefix = "offer_pool_legends_data_"
  const marker = 'const data = '
  const all = Object.values(triggers || {})
    .filter((t) => t && typeof t.name === 'string' && t.name.startsWith(dataPrefix) && typeof t.script === 'string')
    .flatMap((t) => { const at = t.script.indexOf(marker); return at < 0 ? [] : JSON.parse(t.script.slice(at + marker.length)) })
    .filter((e) => !((storage["legendsDone"] || []).includes(e.id)))
  const slots = ["any", "any", "any"]
  let eligible = []
  while (rankAt >= 0) {
    eligible = all.filter((e) => e.rank === poolRanks[rankAt])
    if (eligible.length >= slots.length) break
    rankAt--
  }
  if (eligible.length < slots.length) {
    skip = true
  } else {
    storage.offerPools = storage.offerPools || {}
    const memory = storage.offerPools["legends"] = storage.offerPools["legends"] || { recent: [] }
    const picks = []
    const pickFrom = (list) => list[Math.floor(Math.random() * list.length)]
    const tick = check({ type: 'game-tick' }) || 0
    const held = (memory.current || []).map((id) => eligible.find((e) => e.id === id)).filter(Boolean)
    if (held.length === slots.length && tick - (memory.shownAt || 0) < 20) picks.push(...held)
    for (const slot of slots) {
      if (picks.length >= slots.length) break
      const open = eligible.filter((e) => !picks.includes(e) && (slot === 'any' || e.kind === slot))
      const fits = open
      const fresh = fits.filter((e) => !memory.recent.includes(e.id))
      const choice = pickFrom(fresh.length > 0 ? fresh : fits)
      if (choice) picks.push(choice)
    }
    memory.recent = memory.recent.concat(picks.map((e) => e.id)).slice(-9)
    if ((memory.current || []).join() !== picks.map((e) => e.id).join()) { memory.current = picks.map((e) => e.id); memory.shownAt = tick }
    const framing = "The Legends wall in the League Hall holds these three legendary deeds right now, from across Larion: work only the greatest heroes take, each a deed people will tell of for a generation. When the party reads the wall or asks for legendary work, present exactly these three as separate postings in plain in-fiction prose, each with where it lies and whom it serves. Keep each posting's situation, place and reward; invent fresh names for anyone it describes only by role, and bring the people it sketches to life as described. Each one shown is now open to the party as a quest they can take on, wherever in Larion it lies. Do not replace these with other work or add more, and do not assume the party takes any. If a posting names someone who has died, left, or can no longer help, someone close to them or to the place brings the same work instead; never bring a character back or move them to fit a posting."
    effects.push({ type: 'story', instruction: framing + '\n\n' + picks.map((e, n) => (n + 1) + '. ' + e.text).join('\n\n') })
