legend_ledger.script:
const marker = 'const data = '
const fsrc = Object.values(triggers || {}).find((t) => t && t.name === "legend_factions_data")
const cfg = fsrc ? JSON.parse(fsrc.script.slice(fsrc.script.indexOf(marker) + marker.length)) : { factions: [], fame: [] }
storage.legends = storage.legends || {}
const g = storage.legends
g.renown = g.renown || {}; g.total = g.total || {}; g.led = g.led || {}; g.seats = g.seats || []; g.owned = g.owned || []
const legends = Object.values(triggers || {}).filter((t) => t && typeof t.name === 'string' && t.name.startsWith('offer_pool_legends_data_')).flatMap((t) => JSON.parse(t.script.slice(t.script.indexOf(marker) + marker.length)))
storage.legendsDone = storage.legendsDone || []
const found = legends.filter((e) => storage['legendDone_' + e.id] === true && !storage.legendsDone.includes(e.id))
if (found.length === 0) { skip = true } else {
  const characters = Object.keys(check({ type: 'player-traits' }) || {})
  const lines = []
  for (const e of found) {
    const f = cfg.factions.find((x) => x.id === e.faction)
    storage.legendsDone.push(e.id)
    let champion = false, leader = false, fame = null
    for (const c of characters) {
      g.renown[c] = g.renown[c] || {}
      const r = g.renown[c][e.faction] = (g.renown[c][e.faction] || 0) + 1
      const t = g.total[c] = (g.total[c] || 0) + 1
      if (r === 2) champion = true
      if (r === 4) leader = true
      for (const [n, name] of cfg.fame) if (t === n) fame = name
    }
    lines.push('Word of the deed spreads: ' + e.title + ' is done, and ' + (f ? f.name : 'the League') + ' will tell of it.')
    const per = (cfg.legends || {})[e.id] || {}
    const cap = (s) => s.charAt(0).toUpperCase() + s.slice(1)
    if (per.trophy) effects.push({ type: 'player-traits', operator: 'add', value: per.trophy, target: 'allPlayers' })
    if (f && champion) { effects.push({ type: 'player-traits', operator: 'add', value: f.champion, target: 'allPlayers' }); lines.push(cap(f.authority) + ' name the party ' + f.champion + ' when next they meet.') }
    if (f && leader) {
      effects.push({ type: 'player-traits', operator: 'add', value: f.leader, target: 'allPlayers' })
      g.led[f.id] = true
      if (!g.seats.includes(f.id)) g.seats.push(f.id)
      effects.push({ type: 'write-boolean', key: 'legendSeatGranted', operator: 'set', value: true })
      effects.push({ type: 'write-boolean', key: 'legendFactionLed', operator: 'set', value: true })
      lines.push(cap(f.authority) + ' name the party ' + f.leader + ', one of the leaders of ' + f.name + ', and grant them a seat: ' + f.seat.name + ', ' + f.seat.what + '. When the party next meets them, say its name exactly, ' + f.seat.name + ', and offer them the job of going to take possession of it. It has stood empty a while, so one small trouble waits there, such as pests, a leaking roof or an uninvited lodger; never a villain.')
    }
    if (fame) { effects.push({ type: 'player-traits', operator: 'add', value: fame, target: 'allPlayers' }); lines.push('The party is now ' + fame + '.') }
  }
  effects.push({ type: 'story', instruction: lines.join(' ') })
}

