offer_pool_inquisition.script:
const location = check({ type: 'party-location' }) || ''
const area = check({ type: 'party-area' }) || ''
const region = check({ type: 'party-region' }) || ''
const spaces = ["Black Tower||The Hall of Shadow"]
if (!spaces.includes(location + '||' + area)) { skip = true }
if (!skip) {
  const rankTraits = ["Shadow Initiate", "Shadow Inquisitor", "Inquisition Adept", "Master Inquisitor"]
  const poolRanks = ["initiate", "inquisitor", "adept", "master"]
  const traitsByCharacter = check({ type: 'player-traits' }) || {}
  let rankIndex = -1
  for (const list of Object.values(traitsByCharacter)) {
    let i = rankTraits.length - 1
    const holds = (t) => Array.isArray(t) ? t.some((x) => list.includes(x)) : list.includes(t)
    while (i >= 0 && !holds(rankTraits[i])) i--
    if (i < 0) continue
    const own = Math.max(0, i)
    rankIndex = rankIndex < 0 ? own : Math.min(rankIndex, own)
  }
  let rankAt = Math.min(Math.max(0, rankIndex), poolRanks.length - 1)
  const dataPrefix = "offer_pool_inquisition_data_"
  const marker = 'const data = '
  const all = Object.values(triggers || {})
    .filter((t) => t && typeof t.name === 'string' && t.name.startsWith(dataPrefix) && typeof t.script === 'string')
    .flatMap((t) => { const at = t.script.indexOf(marker); return at < 0 ? [] : JSON.parse(t.script.slice(at + marker.length)) })
    .filter((e) => e.region === region)
  const slots = ["any", "any", "any"]
  let eligible = []
  while (rankAt >= 0) {
    eligible = all.filter((e) => e.rank === poolRanks[rankAt])
    if (eligible.length >= slots.length) break
    rankAt--
  }
  if (eligible.length < slots.length) {
    skip = true
  } else {
    storage.offerPools = storage.offerPools || {}
    const memory = storage.offerPools["inquisition"] = storage.offerPools["inquisition"] || { recent: [] }
    const picks = []
    const pickFrom = (list) => list[Math.floor(Math.random() * list.length)]
    for (const slot of slots) {
      const open = eligible.filter((e) => !picks.includes(e) && (slot === 'any' || e.kind === slot))
      const newKind = open.filter((e) => !picks.some((p) => p.kind === e.kind))
      const fits = slot === 'any' && newKind.length > 0 ? newKind : open
      const fresh = fits.filter((e) => !memory.recent.includes(e.id))
      const choice = pickFrom(fresh.length > 0 ? fresh : fits)
      if (choice) picks.push(choice)
    }
    memory.recent = memory.recent.concat(picks.map((e) => e.id)).slice(-12)
    const framing = "The case boards in the Hall of Shadow hold these three cases for the party's Inquisition rank right now. When the party reads the boards or asks for Tower work, present exactly these three as separate cases in plain in-fiction prose; Jett or an Inquisitor nearby may point them out. Keep each case's situation, place and reward; invent fresh names for anyone it describes only by role, and bring the people it sketches to life as described. A hidden truth in brackets is for you alone: never read it out or hint at it in the case, and let it come out only through the investigation. For an Initiate, each case is offered as their one supervised qualifying case: a mentor from the Tower goes along to watch and advise, never to solve it. An Initiate whose qualifying case is already recognized is told to go to the Pit for the Rite of Bonding instead of taking another. Do not replace these with other cases or add more, and do not assume the party takes any. If a posting names someone who has died, left, or can no longer help, someone close to them or to the place brings the same work instead; never bring a character back or move them to fit a posting."
    effects.push({ type: 'story', instruction: framing + '\n\n' + picks.map((e, n) => (n + 1) + '. ' + e.text).join('\n\n') })
  }
}

