storage.nobleRoll = storage.nobleRoll || {}
const R = storage.nobleRoll
R.people = R.people || {}; R.claimed = R.claimed || []; R.seats = R.seats || []
const T = check({ type: 'player-traits' }) || {}
const location = check({ type: 'party-location' }) || ''
const area = check({ type: 'party-area' }) || ''
const tick = check({ type: 'game-tick' }) || 0
const here = cfg.courts.find((c) => c.locations.includes(location))
const TITLES = ['Knight', 'Baron', 'Count']
const ORDER = ['', 'Noble-born', 'Knight', 'Baron', 'Count']
const rankOf = (l) => l.includes('Count') ? 'Count' : l.includes('Baron') ? 'Baron' : l.includes('Knight') ? 'Knight' : l.includes('Noble Heritage') ? 'Noble-born' : ''
const person = (n) => (R.people[n] = R.people[n] || { court: '', deeds: 0, t: -1, spouse: '' })
const courtOf = (id) => cfg.courts.find((c) => c.id === id) || cfg.recognized.find((c) => c.id === id) || { id: id, name: id }
const styled = (n) => { const r = rankOf(T[n] || []); return r && r !== 'Noble-born' ? n + ' (' + r + ')' : n }
const raise = (to) => {
  effects.push({type:'player-traits',operator:'add',value:'Recognized Noble Title',target:'satisfyingPlayers'})
  for (const t of TITLES) if (t !== to) effects.push({ type: 'player-traits', operator: 'remove', value: t, target: 'satisfyingPlayers' })
  effects.push({ type: 'player-traits', operator: 'add', value: to, target: 'satisfyingPlayers' })
}
const grantSeat = (n, court, rank) => {
  const kinds = rank === 'Count' ? ['count'] : ['town', 'country']
  const kind = kinds.find((k) => court.seats && !R.claimed.includes(court.seats[k].name))
  if (!kind) return ''
  const seat = court.seats[kind]
  R.claimed.push(seat.name)
  R.seats.push({ owner: n, court: court.id, name: seat.name, kind: kind === 'town' ? 'town' : 'country', location: kind === 'town' ? court.seatLocation : seat.name, visited: false, rested: -99 })
  return ' With the title the court grants ' + n + ' a seat: ' + seat.name + ', ' + seat.what + '. When ' + n + ' next speaks with the herald or the duke, say its name exactly, ' + seat.name + ', and offer them the job of going to take possession of it. It has stood empty a while, so one small trouble waits there, such as pests, a leaking roof or an uninvited lodger; never a villain.'
}
const seat = R.seats.find((s) => s.kind === 'country' ? location === s.location : s.kind === 'town' ? location === s.location && (s.court === 'aldwall' && s.name === 'Crownstone House' ? ['The Round Room','The Kitchen Garden'].includes(area) : area.indexOf(s.name) >= 0) : location === s.location && (!s.area || area === s.area))
const key = seat ? seat.owner + '|' + seat.name : ''
if (!seat) { R.homeAt = ''; skip = true } else if (R.homeAt === key) { skip = true } else {
  R.homeAt = key
  const title = rankOf(T[seat.owner] || [])
  const canRest = tick - (typeof seat.rested === 'number' ? seat.rested : -99) >= 10
  let text
  if (seat.kind === 'spouse') text = 'This is the home ' + seat.owner + ' shares with ' + seat.spouse + '.'
  else if (!seat.visited) text = 'This is ' + seat.name + ', the seat of ' + seat.owner + (title ? ' as ' + title : '') + ' of ' + courtOf(seat.court).name + '. A steward is here to greet them by that title and hand over the keys.'
  else text = 'The party is home at ' + seat.name + ', the seat of ' + seat.owner + '. The steward greets them by title.'
  if (['drusavia','oasis','wintercrown','westmarch','aldwall'].includes(seat.court)) text = (seat.visited ? 'The party returns to ' : 'The party arrives at ') + seat.name + ', the furnished home of ' + seat.owner + '. Preserve their privacy and the independent lives of its residents. Stage an ordinary activity appropriate to current relationships; do not reset introductions or require a welcoming ceremony.'
  seat.visited = true
  if (canRest) {
    seat.rested = tick
    text += ' They can rest here in comfort.'
    for (const resource of ['health', 'mana', 'stamina']) effects.push({ type: 'player-resource', target: 'allPlayers', resource, operator: 'add', value: 9999 })
  }
  if (['carendon','tevantia','drusavia','oasis','wintercrown','westmarch','aldwall'].includes(seat.court)) text += ' Use this estate\'s authored residents and current relationships. Show one ordinary activity or personal response to the return, not a compulsory problem or a generic new steward. Invited companions belong here too. Preserve co-owners and their private rooms.'
  effects.push({ type: 'story', instruction: text })
}

