if (nsrc) cfg.nobles = (cfg.nobles || []).concat(JSON.parse(nsrc.script.slice(nsrc.script.indexOf(marker) + marker.length)))
storage.nobleRoll = storage.nobleRoll || {}
const R = storage.nobleRoll
