const T = check({ type: 'player-traits' }) || {}
const location = check({ type: 'party-location' }) || ''
const area = check({ type: 'party-area' }) || ''
const tick = check({ type: 'game-tick' }) || 0
const courtSpaces = [["Ducal Hill", "The Palace"], ["Tevantia", "Ducal Palace - Gilded Hall"], ["Drusavia", "Ducal Square"], ["Marrenford", "Castle Westvigil"], ["Aldwall", "The Duke's Hall"], ["Warmwater Township", "The Winter Court"], ["Oasis", "The Citadel of Seven Winds"]]
const here = courtSpaces.some(([l,a]) => l === location && a === area) ? cfg.courts.find((c) => c.locations.includes(location)) : undefined
const TITLES = ['Knight', 'Baron', 'Count']
const ORDER = ['', 'Noble-born', 'Knight', 'Baron', 'Count']
const rankOf = (l) => l.includes('Count') ? 'Count' : l.includes('Baron') ? 'Baron' : l.includes('Knight') ? 'Knight' : l.includes('Noble Heritage') ? 'Noble-born' : ''
const person = (n) => (R.people[n] = R.people[n] || { court: '', deeds: 0, t: -1, spouse: '' })
const courtOf = (id) => cfg.courts.find((c) => c.id === id) || cfg.recognized.find((c) => c.id === id) || { id: id, name: id }
const styled = (n) => { const r = rankOf(T[n] || []); return r && r !== 'Noble-born' ? n + ' (' + r + ')' : n }
const raise = (to) => {
  effects.push({type:'player-traits',operator:'add',value:'Recognized Noble Title',target:'satisfyingPlayers'})
  for (const t of TITLES) if (t !== to) effects.push({ type: 'player-traits', operator: 'remove', value: t, target: 'satisfyingPlayers' })
  effects.push({ type: 'player-traits', operator: 'add', value: to, target: 'satisfyingPlayers' })
}
const grantSeat = (n, court, rank) => {
  const kinds = rank === 'Count' ? ['count'] : ['town', 'country']
  const kind = kinds.find((k) => court.seats && !R.claimed.includes(court.seats[k].name))
  if (!kind) return ''
  const seat = court.seats[kind]
  R.claimed.push(seat.name)
  R.seats.push({ owner: n, court: court.id, name: seat.name, kind: kind === 'town' ? 'town' : 'country', location: kind === 'town' ? court.seatLocation : seat.name, visited: false, rested: -99 })
  return ' With the title the court grants ' + n + ' a seat: ' + seat.name + ', ' + seat.what + '. When ' + n + ' next speaks with the herald or the duke, say its name exactly, ' + seat.name + ', and offer them the job of going to take possession of it. It has stood empty a while, so one small trouble waits there, such as pests, a leaking roof or an uninvited lodger; never a villain.'
}
const lines = []
storage.atNobleCourt = !!here
storage.nobleCourtId = here ? here.id : ''
const present = cfg.nobles.filter((e) => check({ type: 'npc-in-scene', npc: e.name }))
// A court matter can also be accepted directly from a known household representative.
storage.courtEntryAvailable = !!here || present.length > 0
if (!here) { R.at = '' } else {
  for (const n in T) {
    const p = person(n)
    if (!p.court && T[n].includes('Noble Heritage') && R.at !== here.id) { lines.push('The herald receives ' + n + ' as a noble-born visitor. Preserve their established family and origin; visiting ' + here.name + ' does not make it their home court or pledge their allegiance.') }
  }
  if (R.at !== here.id) {
    R.at = here.id
    const known = Object.keys(T).filter((n) => rankOf(T[n]) || person(n).court).map((n) => {
      const p = person(n), r = rankOf(T[n]) || 'no rank', c = p.court ? courtOf(p.court).name : 'no court yet'
      const next = { '': 'Knight', 'Noble-born': 'Knight', Knight: 'Baron', Baron: 'Count' }[rankOf(T[n])]
