  }
}
if (lines.length) effects.push({ type: 'story', instruction: lines.join(' ') + ' Bring this in only where it fits the scene; never recite it.' })
else skip = true

legends_abroad.script:
const GAP = 60
const CHANCE = 0.2
const REPEAT = 300
const TOWNS = ["Aldwall", "Ardan's Watch", "Argenval", "Beggarsbridge", "Brackenhill Village", "Branton", "Burlwick", "Camp Drokash", "Canopy", "Caranthoria", "Carendon", "Citadel Uchaghar", "Clachmore Village", "Clanhold Deepfire", "Clanhold Icerune", "Clanhold Stonewall", "Clanhold Stormhammer", "Cloudtop", "Confluence", "Copperstone", "Coriva", "Crescent Bay Isle", "Deepgate", "Dimbly Hatchery", "Drakerider Isle", "Drusavia", "Ducal Hill", "Dun Beithir", "Dun Solas", "Durg Sthira", "Eanleana", "Earthsky Island", "Eelfen Village", "Fallsmeet", "Forge-town", "Freehaven", "Garden", "Gavarra", "Goldentor", "Gorren Crossing", "Greathearth", "Greenmeadow", "Hag's Rock", "Hillhome", "Ilunethel", "Kalanth Landing", "Kingstor", "Kolbeck", "Longrun", "Maanvalta", "Marrenford", "Morcroft Hall", "Mounagiri", "Mudbank", "New Anthara", "Nocturne", "Oasis", "Port Lucre", "Rathcairn", "Reedmoot", "Revanasi Village", "Ronansay Village", "Rovena", "Saffra", "Sanctuary", "Sangamadi", "Serendipity", "Shilaghar", "Smoketown", "Tarnport", "Tethwell Hotsprings", "Tevantia", "The Crossroads Inn", "The Folkmoot", "The Main Island", "The Wildmarket", "Tuskhollow", "Vaudania", "Vigil Gorge", "Vilitara Grove", "Vorren's Hold", "Waldgate", "Warmwater Township", "Willowford", "Wortwell"]
const POOL = {"Kaivara": ["A huge claw punches through a tear in the air above an open public space. Kaivara catches it in a ring of pale-gold force, hauls the creature halfway through, and strikes it with three thunderous blasts before forcing it back and closing that tear. Smaller creatures have spilled through and the breach is not yet secure. She calls on nearby armed people to keep them off her while she seals it. Establish her spectacular power; give the party room to fight the escaped creatures, protect bystanders, help with the breach, or decline involvement. Do not decide player actions. Treat the initial display as the arrival setup, then resolve ongoing attacks and outcomes through normal combat; do not predeclare the encounter won.", "She's at the inn buying a rare reagent at an outrageous price, and she is more interested in the person standing next to her than in the haggling.", "She's resting before a long walk, alone at a corner table with tea, and she seems to have expected the party.", "She followed something here, and she asks whether anyone in town has had strange dreams lately."], "Malphira": ["She has taken the best room at the inn and is holding court in the common room, buying drinks for anyone with a good story, and she wants to hear the party's.", "There's a duel at dawn, and she has quietly paid both duelists' debts on condition that they fight to the death.", "She's watching a public punishment from the front row with a glass of wine, and she asks the nearest stranger whether they think the prisoner deserves it.", "She has just won a fortune at cards from the richest man in town, and he is beginning to wonder how."], "Quillon": ["Armed extortionists interrupt a tavern celebration. Quillon turns their leader’s raised sword into flowers with a single note. The others move to attack. He invites nearby adventurers to help while the guests escape; the player can fight, negotiate, protect people, or stay clear. Resolve the continuing confrontation normally.", "Quillon has staked his fiddle against a wealthy bully’s confiscated instruments. He invites an independent witness to inspect the coin before the toss. The player can expose cheating, propose different terms, or simply watch.", "His music is drawing increasingly reckless truths from the guests at a wedding, and one angry relative demands that he stop. The player can challenge his amusement, help rescue the celebration, or pursue what has been revealed. Never supply a confession for the player.", "Small strokes of good luck follow gifts placed in his hat in the market. He offers to teach a willing traveler a tune in exchange for a song from their own travels. The exchange offers an early chance to notice how much he knows."], "Morrow": ["A violent ghost tears a door from its hinges. Morrow catches it in a mass of pale hands and slams it against the empty street, frost spreading across the stones. She has checked its first rush, but it is gathering itself to attack again. She asks nearby armed people to help keep it away from the occupied houses so she can discover what holds it here. The party can fight beside her, protect residents, seek the haunting’s cause, or decline. Resolve further attacks normally. Its identity and grievance remain discoverable; Morrow’s own condition is not announced.", "She's sitting at the bedside of a dying stranger so they won't be alone, and the family doesn't know what to make of her.", "She's looking for an unmarked grave nearby, and asking the oldest people in town what they remember.", "She's carrying a dead soldier's last words home to his mother, and she has just found the house."], "Talis": ["She's at a corner table in the inn with her back to the wall, and she has just noticed that someone at the bar knows her name.", "She's lying low for a night, and she pays the party, quietly, to tell her if anyone comes asking about a woman in a red scarf.", "She has just caught a pickpocket's wrist without looking up, and she is now the center of attention, which she hates.", "She's on her way out of town, but a child here is having nightmares that aren't natural, and she can't leave it alone."]}
const tick = Number(check({ type: 'game-tick' })) || 0
const here = check({ type: 'party-location' }) || ''
skip = true
if (here && here !== storage.legendsLastLocation) {
  storage.legendsLastLocation = here
  const out = []
  const prev = storage.legendsCurrent
  if (prev) {
    const stayed = check({ type: 'npc-in-party', npc: prev }) === true || check({ type: 'npc-location', npc: prev }) === here
    if (!stayed) out.push({ type: 'npc-placement', npc: prev, operation: 'moveAway' })
    storage.legendsCurrent = ''
  }
  const seen = storage.legendsSeen || {}
  if (TOWNS.includes(here) && tick - (Number(storage.legendsLastTick) || -100000) >= GAP && Math.random() < CHANCE) {
    const free = Object.keys(POOL).filter((k) => Number(check({ type: 'npc-health-percent', npc: k })) > 0
      && check({ type: 'npc-in-party', npc: k }) !== true
      && check({ type: 'npc-location', npc: k }) !== here
      && tick - (Number(seen[k]) || -100000) >= REPEAT)
    if (free.length) {
      const k = free[Math.floor(Math.random() * free.length)]
      const firstKaivaraMeeting = k === 'Kaivara' && !Object.prototype.hasOwnProperty.call(seen, k)
      const firstMorrowMeeting = k === 'Morrow' && !Object.prototype.hasOwnProperty.call(seen, k)
      const why = (firstKaivaraMeeting || firstMorrowMeeting) ? POOL[k][0] : POOL[k][Math.floor(Math.random() * POOL[k].length)]
      out.push({ type: 'npc-placement', npc: k, operation: 'moveHere' })
      out.push({ type: 'story', instruction: k + ' is here, passing through. ' + why + ' Bring them into this scene naturally, as someone the party notices or crosses paths with; do not force a meeting.' })
      seen[k] = tick
      storage.legendsSeen = seen
      storage.legendsCurrent = k
      storage.legendsLastTick = tick
      storage.initiativeCooldown = Math.max(Number(storage.initiativeCooldown) || 0, 20)
    }
  }
  if (out.length) { effects = out; skip = false }
}

