}

carendon_standing_request.script:
const T=check({type:'player-traits'})||{};const R=storage.nobleRoll||{people:{},seats:[]};const lines=[]
for(const n of Object.keys(T)){const list=T[n];const rank=['Count','Baron','Knight'].find(t=>list.includes(t))||(list.includes('Noble Heritage')?'Noble-born':'untitled');const progress=['Carendon: Three Services','Carendon: Two Services','Carendon: One Service'].findIndex(t=>list.includes(t));const count=progress<0?0:3-progress;const need=rank==='Knight'?3:rank==='Baron'?4:rank==='Noble-born'?1:rank==='Count'?0:2;const homes=(R.seats||[]).filter(s=>s.owner===n&&s.court==='carendon').map(s=>s.name);lines.push(n+': '+rank+(need?', '+count+' of '+need+' services toward the next title':'')+(homes.length?'; granted home: '+homes.join(', '):''))}
effects.push({type:'story',instruction:'The following gives the characters’ current standing and overrides earlier mistaken dialogue. Correct any earlier claim that a Galard oath or three Proving-Year deeds are required for a Carendon title. Court titles and religious advancement are independent; Dalia speaks for Carendon, not Galard. Name their title and explain its privileges now: '+lines.join('; ')+'. Any capable person may ask for matters before the court. Meaningful completed matters are recognized once per participant; disagreement with a patron is allowed. Knights have Palace guest quarters and access to officers; Barons receive a home and can host company and decide local estate matters; Counts hold a share of Fernvale and can ask to join important court deliberations. Other Greater Duchies honor these titles, but personal trust is earned there. No rank makes someone immune to law or ready for every fight. Do not assign a family or an oath.'})

for (const e of effects) { if (e.type === "story") e.instruction += " Recognize service through conversation, public thanks, introductions and hospitality. Internal progress tracking is not a physical ledger or document: do not stage bookkeeping, forms, stamps or paperwork as part of recognition." }

offer_pool_carendon_court.script:
const location = check({ type: 'party-location' }) || ''
const area = check({ type: 'party-area' }) || ''
const region = check({ type: 'party-region' }) || ''
const spaces = ["Ducal Hill||The Palace"]
if (!spaces.includes(location + '||' + area)) { skip = true }
if (!skip) {
  const rankTraits = []
  const poolRanks = ["service"]
  const traitsByCharacter = check({ type: 'player-traits' }) || {}
  let rankIndex = -1
  for (const list of Object.values(traitsByCharacter)) {
    let i = rankTraits.length - 1
    const holds = (t) => Array.isArray(t) ? t.some((x) => list.includes(x)) : list.includes(t)
    while (i >= 0 && !holds(rankTraits[i])) i--
    const own = Math.max(0, i)
    rankIndex = rankIndex < 0 ? own : Math.min(rankIndex, own)
  }
  let rankAt = Math.min(Math.max(0, rankIndex), poolRanks.length - 1)
  const dataPrefix = "offer_pool_carendon_court_data_"
  const marker = 'const data = '
  const all = Object.values(triggers || {})
    .filter((t) => t && typeof t.name === 'string' && t.name.startsWith(dataPrefix) && typeof t.script === 'string')
    .flatMap((t) => { const at = t.script.indexOf(marker); return at < 0 ? [] : JSON.parse(t.script.slice(at + marker.length)) })
    .filter((e) => e.region === region)
    .filter((e) => !((storage["carendonMattersDone"] || []).includes(e.id)))
  const slots = ["social", "social", "combat"]
  let eligible = []
  while (rankAt >= 0) {
    eligible = all.filter((e) => e.rank === poolRanks[rankAt])
    if (eligible.length > 0) break
    rankAt--
  }
  if (eligible.length === 0) {
    effects.push({type: 'story', instruction: "Dalia says the listed matters have been settled. Acknowledge what the party changed, offer ordinary company or discuss their home and an invitation to another court if relevant. Do not recycle a finished matter, manufacture an urgent chore or award service for asking."})
  } else {
    storage.offerPools = storage.offerPools || {}
    const memory = storage.offerPools["carendon-court"] = storage.offerPools["carendon-court"] || { recent: [] }
    const picks = []
    const pickFrom = (list) => list[Math.floor(Math.random() * list.length)]
    const tick = check({ type: 'game-tick' }) || 0
    const held = (memory.current || []).map((id) => eligible.find((e) => e.id === id)).filter(Boolean)
    if (held.length === slots.length && tick - (memory.shownAt || 0) < 12) picks.push(...held)
    for (const slot of slots) {
      if (picks.length >= slots.length) break
      const open = eligible.filter((e) => !picks.includes(e) && (slot === 'any' || e.kind === slot))
      const fits = open
      const fresh = fits.filter((e) => !memory.recent.includes(e.id))
