  effects.push({ type: 'player-traits', operator: 'add', value: to, target: 'satisfyingPlayers' })
}
const grantSeat = (n, court, rank) => {
  const kinds = rank === 'Count' ? ['count'] : ['town', 'country']
  const kind = kinds.find((k) => court.seats && !R.claimed.includes(court.seats[k].name))
  if (!kind) return ''
  const seat = court.seats[kind]
  R.claimed.push(seat.name)
  R.seats.push({ owner: n, court: court.id, name: seat.name, kind: kind === 'town' ? 'town' : 'country', location: kind === 'town' ? court.seatLocation : seat.name, visited: false, rested: -99 })
