const cfg = src ? JSON.parse(src.script.slice(src.script.indexOf(marker) + marker.length)) : { courts: [], recognized: [], nobles: [], thresholds: {} }
const nsrc = Object.values(triggers || {}).find((t) => t && t.name === 'noble_court_nobles_data')
if (nsrc) cfg.nobles = (cfg.nobles || []).concat(JSON.parse(nsrc.script.slice(nsrc.script.indexOf(marker) + marker.length)))
