}

const names=Object.keys(T).filter(n=>rankOf(T[n]||[])===""&&(T[n]||[]).includes("Court service confirmed: commoner")&&(T[n]||[]).includes("Court service (Commoner): 0/2"));const lines=[];
for(const n of names){const p=person(n);if(!p.court&&here)p.court=here.id;p.deeds=1;p.t=tick;lines.push(n+" now has 1/2 services toward Knight.");}
if(lines.length)effects.push({type:"story",instruction:lines.join(" ").slice(0,1000)});

