const here = cfg.courts.find((c) => c.locations.includes(location))
const TITLES = ['Knight', 'Baron', 'Count']
const ORDER = ['', 'Noble-born', 'Knight', 'Baron', 'Count']
const rankOf = (l) => l.includes('Count') ? 'Count' : l.includes('Baron') ? 'Baron' : l.includes('Knight') ? 'Knight' : l.includes('Noble Heritage') ? 'Noble-born' : ''
const person = (n) => (R.people[n] = R.people[n] || { court: '', deeds: 0, t: -1, spouse: '' })
