tevantia_service_hearing_request.script:
const marker = 'const data = '
const data = Object.values(triggers).filter(t => t.name.startsWith('offer_pool_tevantia_court_data_')).flatMap(t => JSON.parse(t.script.split(marker)[1]))
const done = storage.tevantiaMattersDone || []
const heard = storage.tevantiaMattersHeard || []
const action = String(check({type:'action-text'}) || '').toLowerCase()
const explicit = data.find(e => done.includes(e.id) && action.includes(e.title.toLowerCase()))
const matter = explicit || data.find(e => done.includes(e.id) && !heard.includes(e.id))
if (!matter) { storage.tevantiaMatterBeingHeard = ''; effects.push({type:'story', instruction:'Rosalba explains that she can hear a completed matter and recognize the people who actually helped. No unrecognized completed matter is waiting. If someone has an unrecognized part in a matter already heard, ask them which one. Ordinary favors earn thanks; do not invent a completed service.'}) }
else { storage.tevantiaMatterBeingHeard = matter.id; effects.push({type:'story', instruction:'Rosalba hears one matter now: ' + matter.title + '. Ask for the participants and their account or witnesses. If the completed outcome is supported, explicitly recognize each named player character who actually contributed. Do not credit absent nonparticipants, invent proof, demand obedience to the patron, count a second matter in this hearing, or announce a new rank before it is granted. Keep court service separate from Galard\'s Proving Year or any other faction: Rosalba recognizes Tevantia service only. Recognition does not pay the quest reward again or make the same completed deed a second achievement. A patron may already have paid it. The character may dispute the account or leave.'}) }

for (const e of effects) { if (e.type === "story") e.instruction += " Recognize service through conversation, public thanks, introductions and hospitality. Internal progress tracking is not a physical ledger or document: do not stage bookkeeping, forms, stamps or paperwork as part of recognition." }

const recognition = triggers["tevantia_recognize_matter"]
const stableQuery = recognition.conditions.find(c => c.type === 'story')
recognition.effects = []
recognition.script = 'skip = true'
recognition.conditions = [{type:'read-boolean',key:"tevantiaRecognitionConfigured",operator:'equals',value:true}, stableQuery]
if (matter) {
 const receipt = "Tevantia Service: " + matter.title
 recognition.conditions = [
  {type:'game-tick',operator:'equals',value:check({type:'game-tick'})},
  {type:'quests-completed',operator:'contains',value:matter.title},
  {type:'player-traits',operator:'notContains',value:receipt},
  {type:'player-traits',operator:'notContains',value:"Tevantia Service Being Recorded"},stableQuery]
 const awards = [receipt,"Tevantia Service Being Recorded",'Court Path Active'].map(value => ({type:'player-traits',operator:'add',value,target:'satisfyingPlayers'}))
 recognition.script = "if (check({type:'party-location'}) !== " + JSON.stringify("Tevantia") + " || check({type:'party-area'}) !== " + JSON.stringify("Ducal Palace - Gilded Hall") + ") skip = true; if (!skip) effects.push(..." + JSON.stringify(awards) + "); if (!skip) { storage.tevantiaMattersHeard = storage.tevantiaMattersHeard || []; if (!storage.tevantiaMattersHeard.includes(" + JSON.stringify(matter.id) + ")) storage.tevantiaMattersHeard.push(" + JSON.stringify(matter.id) + "); }"
}

