initiative_silvervale_director.script:
skip = true
const readData = (prefix) => Object.values(triggers || {})
  .filter((t) => t && typeof t.name === 'string' && t.name.startsWith(prefix) && typeof t.script === 'string')
  .flatMap((t) => { const at = t.script.indexOf('const data = '); return at < 0 ? [] : JSON.parse(t.script.slice(at + 13)) })
const inCombat = check({ type: 'npc-in-combat', npc: 'anySceneNPC', operator: 'equals', value: true }) === true
const busy = !inCombat && readData('initiative_silvervale_events_data').some((id) => check({ type: 'narrative-event-status', eventId: id, operator: 'equals', value: 'active' }) === true)
const norm = (s) => String(s || '').trim().toLowerCase().replace(/^the\s+/, '')
const here = check({ type: 'party-location' }) || ''
const area = norm(check({ type: 'party-area' }))
const excluded = {"Ardan's Watch": ["The Dry Cistern", "The Crooked Cellar"], "Muckside": ["The Muckwarren", "The Plague Crypts", "The Hall of Skulls"], "The Crossroads Inn": ["The Royal Chamber"], "The Field of Valor": ["The Masters' Manor"], "Greenmeadow": ["Meadowcourt"], "The City of Ancestors": ["The Descent", "The Shattered Crypts", "The Ossuary of Kings", "The Ritual Chamber"], "Demon's Head Ruins": ["The Flooded Court", "The Relland Keep", "The Old Armory", "The Relland Vaults"]}
if (!inCombat && !busy && !(excluded[here] || []).map(norm).includes(area)) {
  const hub = here === "Ardan's Watch"
  const known = (["Bellwether's Land Office", "Champion's Row", "Mercy House", "Old Town", "The Bargain Hoard", "The Basement", "The Delvers' Lift", "The Fist & Flagon", "The High City", "The Hippogriff Roost", "The Imp-orium", "The Overburden", "The Sacred Way", "The Way of Coin", "Thousandlights Market", "Watchtower - League Hall", "Watchtower - Map Room", "Watchtower - Portal Hall", "Watchtower - Training Yard"]).map(norm)
  // The counters fire before this script and have already aged the value: 1 means the last narration was leisure.
  const festive = Number(storage.initiativeLeisure) >= 1
  const used = Array.isArray(storage.initiativeUsed) ? storage.initiativeUsed : []
  const fits = (e) => {
    if (e.h !== hub || e.f !== festive || used.includes(e.id) || e.a === here) return false
    if (hub) return e.w.includes('*') || (known.includes(area) && e.w.map(norm).includes(area))
    return e.w.includes(here)
  }
  const open = readData('initiative_silvervale_data_').filter(fits)
  if (open.length) {
    const rows = [...new Set(open.map((e) => e.r))]
    const row = rows[Math.floor(Math.random() * rows.length)]
    const pool = open.filter((e) => e.r === row)
    const e = pool[Math.floor(Math.random() * pool.length)]
    storage.initiativeUsed = used.concat([e.id])
    storage.initiativeCooldown = 20
    storage.initiativeLast = { id: e.id, tick: check({ type: 'game-tick' }) }
    effects.push({ type: 'story', instruction: "Optional World Motion for this turn has been chosen: after the players' actions and their outcomes, include this beat from the life around them. {entry} Make it vivid and specific: something the players will want to know more about. Bring it in through whoever fits best here: someone already in the scene mentioning it, people nearby talking about it, or something the players can see for themselves. Keep it to one or two sentences and place it before any question to the players. After it, the people around the players go back to what they were doing, and the turn ends on the players' own scene. It is an open option the players can take up now, later or never, so nobody presses them for an answer.".replace('{entry}', e.t) })
    skip = false
  }
}

