offer_pool_oasis_court.script:
const location = check({ type: 'party-location' }) || ''
const area = check({ type: 'party-area' }) || ''
const region = check({ type: 'party-region' }) || ''
const spaces = ["Oasis||The Citadel of Seven Winds"]
if (!spaces.includes(location + '||' + area)) { skip = true }
if (!skip) {
  const rankTraits = []
  const poolRanks = ["service"]
  const traitsByCharacter = check({ type: 'player-traits' }) || {}
  let rankIndex = -1
  for (const list of Object.values(traitsByCharacter)) {
    let i = rankTraits.length - 1
    const holds = (t) => Array.isArray(t) ? t.some((x) => list.includes(x)) : list.includes(t)
    while (i >= 0 && !holds(rankTraits[i])) i--
    const own = Math.max(0, i)
    rankIndex = rankIndex < 0 ? own : Math.min(rankIndex, own)
  }
  let rankAt = Math.min(Math.max(0, rankIndex), poolRanks.length - 1)
  const dataPrefix = "offer_pool_oasis_court_data_"
  const marker = 'const data = '
  const all = Object.values(triggers || {})
    .filter((t) => t && typeof t.name === 'string' && t.name.startsWith(dataPrefix) && typeof t.script === 'string')
    .flatMap((t) => { const at = t.script.indexOf(marker); return at < 0 ? [] : JSON.parse(t.script.slice(at + marker.length)) })
    .filter((e) => e.region === region)
    .filter((e) => !((storage["oasisMattersDone"] || []).includes(e.id)))
  const slots = ["any", "any", "any"]
  let eligible = []
  while (rankAt >= 0) {
    eligible = all.filter((e) => e.rank === poolRanks[rankAt])
    if (eligible.length > 0) break
    rankAt--
  }
  if (eligible.length === 0) {
    effects.push({type: 'story', instruction: "Rostam says the listed matters have been settled. Acknowledge what the party changed, offer ordinary company or discuss their home and an invitation to another court if relevant. Do not recycle a finished matter, manufacture an urgent chore or award service for asking."})
  } else {
    storage.offerPools = storage.offerPools || {}
    const memory = storage.offerPools["oasis-court"] = storage.offerPools["oasis-court"] || { recent: [] }
    const picks = []
    const pickFrom = (list) => list[Math.floor(Math.random() * list.length)]
    const tick = check({ type: 'game-tick' }) || 0
    const held = (memory.current || []).map((id) => eligible.find((e) => e.id === id)).filter(Boolean)
    if (held.length === slots.length && tick - (memory.shownAt || 0) < 12) picks.push(...held)
    for (const slot of slots) {
      if (picks.length >= slots.length) break
      const open = eligible.filter((e) => !picks.includes(e) && (slot === 'any' || e.kind === slot))
      const fits = open
      const fresh = fits.filter((e) => !memory.recent.includes(e.id))
      const choice = pickFrom(fresh.length > 0 ? fresh : fits)
      if (choice) picks.push(choice)
    }
    memory.recent = memory.recent.concat(picks.map((e) => e.id)).slice(-6)
    if ((memory.current || []).join() !== picks.map((e) => e.id).join()) { memory.current = picks.map((e) => e.id); memory.shownAt = tick }
    const framing = "Rostam offers the supplied matters as opportunities, never assignments. Briefly explain the people, desired outcome, destination and reward. Never accept for the party. Present only the supplied unresolved matters. A solution may disagree with a patron. On completion, return to Rostam at the Citadel of Seven Winds for a hearing: one matter at a time, each actual participant credited once. Use exact titles, never internal IDs. The patron gives coin and favors in the story; do not pay twice during recognition. These are narrative seeds: invent incidental people, clues and scene details consistently with the premise. Do not require a fixed sequence or predetermined solution. If a posting names someone who has died, left, or can no longer help, someone close to them or to the place brings the same work instead; never bring a character back or move them to fit a posting."
    effects.push({ type: 'story', instruction: framing + '\n\n' + picks.map((e, n) => (n + 1) + '. ' + e.text).join('\n\n') })
    for (const e of picks) effects.push({ type: 'quest-init', operator: 'set', value: e.title })
  }
}

