westmarch_service_hearing_request.script:
const marker = 'const data = '
const data = Object.values(triggers).filter(t => t.name.startsWith('offer_pool_westmarch_court_data_')).flatMap(t => JSON.parse(t.script.split(marker)[1]))
const done = storage.westmarchMattersDone || []
const heard = storage.westmarchMattersHeard || []
const action = String(check({type:'action-text'}) || '').toLowerCase()
const explicit = data.find(e => done.includes(e.id) && action.includes(e.title.toLowerCase()))
const matter = explicit || data.find(e => done.includes(e.id) && !heard.includes(e.id))
if (!matter) { storage.westmarchMatterBeingHeard = ''; effects.push({type:'story', instruction:'Aldo explains that she can hear a completed matter and recognize the people who actually helped. No unrecognized completed matter is waiting. If someone has an unrecognized part in a matter already heard, ask them which one. Ordinary favors earn thanks; do not invent a completed service.'}) }
